export const LATEINISCHE_ZITATE=[{id:'lat1',latein:'Veni, vidi, vici.',uebersetzung:'Ich kam, ich sah, ich siegte.',autor:'Julius Caesar',kontext:'Meldung an den römischen Senat nach seinem raschen Sieg über König Pharnakes II. von Pontos, 47 v. Chr.'},{id:'lat2',latein:'In dubio pro reo.',uebersetzung:'Im Zweifel für den Angeklagten.',autor:'Rechtsgrundsatz (römisches Recht)',kontext:'Grundprinzip des Strafrechts: Bestehen begründete Zweifel an der Schuld, muss zugunsten des Angeklagten entschieden werden.'},{id:'lat3',latein:'Alea iacta est.',uebersetzung:'Der Würfel ist gefallen.',autor:'Julius Caesar',kontext:'Soll Caesar beim Überschreiten des Rubikon 49 v. Chr. gesagt haben – der Punkt ohne Umkehr.'},{id:'lat4',latein:'Carpe diem.',uebersetzung:'Nutze den Tag.',autor:'Horaz',kontext:'Aus den Oden (Buch 1, Ode 11); vollständig „Carpe diem, quam minimum credula postero" – nutze den Tag und vertraue möglichst wenig auf morgen.'},{id:'lat5',latein:'Cogito, ergo sum.',uebersetzung:'Ich denke, also bin ich.',autor:'René Descartes',kontext:'Lateinische Fassung des ursprünglich französischen „Je pense, donc je suis" aus dem Discours de la méthode (1637).'},{id:'lat6',latein:'Errare humanum est.',uebersetzung:'Irren ist menschlich.',autor:'Seneca (zugeschrieben)',kontext:'Vollständig oft zitiert als „Errare humanum est, perseverare diabolicum" – irren ist menschlich, im Irrtum verharren teuflisch.'},{id:'lat7',latein:'Memento mori.',uebersetzung:'Bedenke, dass du sterblich bist.',autor:'Römischer Brauch / Stoische Tradition',kontext:'Erinnerung an die eigene Sterblichkeit als Ansporn, bewusst zu leben; zentral in der stoischen Praxis.'},{id:'lat8',latein:'Audiatur et altera pars.',uebersetzung:'Auch die andere Seite soll gehört werden.',autor:'Rechtsgrundsatz',kontext:'Grundprinzip fairer Verfahren und Diskussionen: Keine Seite darf ohne Anhörung verurteilt werden.'},{id:'lat9',latein:'Cui bono?',uebersetzung:'Wem nützt es?',autor:'Lucius Cassius (überliefert durch Cicero)',kontext:'Von Cicero mehrfach zitierte Frage des römischen Richters Cassius: Wer von einer Tat profitiert, ist oft auch ihr Urheber.'},{id:'lat10',latein:'Dura lex, sed lex.',uebersetzung:'Das Gesetz ist hart, aber es ist das Gesetz.',autor:'Rechtsgrundsatz (römisches Recht)',kontext:'Prinzip, dass geltendes Recht auch dann anzuwenden ist, wenn sein Ergebnis im Einzelfall hart erscheint.'},{id:'lat11',latein:'Festina lente.',uebersetzung:'Eile mit Weile.',autor:'Kaiser Augustus (überliefert durch Sueton)',kontext:'Paradoxes Motto des Augustus: schnell handeln, aber besonnen und ohne Übereilung.'},{id:'lat12',latein:'Nosce te ipsum.',uebersetzung:'Erkenne dich selbst.',autor:'Lateinische Übersetzung des delphischen Orakelspruchs',kontext:'Lateinische Fassung von „Gnothi seauton", das über dem Apollontempel in Delphi stand und von Sokrates aufgegriffen wurde.'},{id:'lat13',latein:'Pacta sunt servanda.',uebersetzung:'Verträge sind einzuhalten.',autor:'Rechtsgrundsatz (römisches Vertragsrecht)',kontext:'Fundamentales Prinzip des Vertrags- und Völkerrechts bis heute.'},{id:'lat14',latein:'Panem et circenses.',uebersetzung:'Brot und Spiele.',autor:'Juvenal',kontext:'Aus Juvenals Satiren (10, 81); Kritik daran, dass sich das römische Volk mit materieller Versorgung und Unterhaltung ruhigstellen ließ, statt politische Mitsprache zu fordern.'},{id:'lat15',latein:'Per aspera ad astra.',uebersetzung:'Durch Widrigkeiten zu den Sternen.',autor:'Seneca (sinngemäß, Hercules Furens)',kontext:'Motiv, dass Großes nur über Mühen und Rückschläge erreichbar ist.'},{id:'lat16',latein:'Mens sana in corpore sano.',uebersetzung:'Ein gesunder Geist in einem gesunden Körper.',autor:'Juvenal',kontext:'Aus Juvenals Satiren (10, 356); ursprünglich als Wunsch formuliert, nicht als Tatsachenbehauptung.'},{id:'lat17',latein:'Si vis pacem, para bellum.',uebersetzung:'Willst du Frieden, rüste zum Krieg.',autor:'Vegetius',kontext:'Aus „Epitoma rei militaris"; Prinzip der Abschreckung durch Stärke.'},{id:'lat18',latein:'Homo homini lupus.',uebersetzung:'Der Mensch ist dem Menschen ein Wolf.',autor:'Plautus, später durch Thomas Hobbes berühmt gemacht',kontext:'Ursprünglich bei Plautus (Asinaria); von Hobbes im Leviathan als Bild des Naturzustands ohne Staat verwendet.'},{id:'lat19',latein:'In vino veritas.',uebersetzung:'Im Wein liegt Wahrheit.',autor:'Sprichwort, überliefert u. a. bei Plinius d. Ä.',kontext:'Beobachtung, dass Alkohol Hemmungen löst und Menschen ehrlicher (oder unvorsichtiger) sprechen lässt.'},{id:'lat20',latein:'Tempus fugit.',uebersetzung:'Die Zeit flieht.',autor:'Vergil',kontext:'Aus den Georgica (3, 284): „Sed fugit interea, fugit irreparabile tempus" – die Zeit flieht unaufhaltsam.'},{id:'lat21',latein:'Quo vadis?',uebersetzung:'Wohin gehst du?',autor:'Vulgata (Johannesevangelium, apokryphe Erweiterung)',kontext:'Frage an Petrus in der Legende, die ihm auf der Flucht aus Rom erscheinende Christusfigur zu stellen.'},{id:'lat22',latein:'Sic transit gloria mundi.',uebersetzung:'So vergeht der Ruhm der Welt.',autor:'Liturgische Tradition, u. a. Papstkrönungen',kontext:'Erinnerung an die Vergänglichkeit von Macht, Ruhm und weltlichem Ansehen.'},{id:'lat23',latein:'Vox populi, vox Dei.',uebersetzung:'Die Stimme des Volkes ist die Stimme Gottes.',autor:'Alkuin (in einem Brief an Karl den Großen, kritisch zitiert)',kontext:'Alkuin warnte tatsächlich davor, diesen Satz unreflektiert zu übernehmen, da der „Lärm der Menge" oft nah am Wahnsinn sei.'},{id:'lat24',latein:'Ad hominem.',uebersetzung:'Gegen den Menschen (statt gegen die Sache).',autor:'Rhetorische Fachsprache',kontext:'Bezeichnet den logischen Fehlschluss, die Person statt ihr Argument anzugreifen.'},{id:'lat25',latein:'Amor vincit omnia.',uebersetzung:'Liebe besiegt alles.',autor:'Vergil',kontext:'Aus den Eklogen (10, 69): „Omnia vincit amor".'},{id:'lat26',latein:'Ars longa, vita brevis.',uebersetzung:'Die Kunst ist lang, das Leben kurz.',autor:'Hippokrates (lateinische Fassung), Seneca griff es auf',kontext:'Ursprünglich griechisch von Hippokrates; Seneca vertiefte den Gedanken in „De brevitate vitae".'},{id:'lat27',latein:'Fortuna audaces iuvat.',uebersetzung:'Das Glück steht den Mutigen bei.',autor:'Vergil',kontext:'Aus der Aeneis (10, 284); ähnlich auch bei Terenz und Cicero überliefert.'},{id:'lat28',latein:'Ignorantia legis non excusat.',uebersetzung:'Unkenntnis des Gesetzes schützt nicht vor Strafe.',autor:'Rechtsgrundsatz (römisches Recht)',kontext:'Grundprinzip, das bis heute in modernen Rechtssystemen gilt.'},{id:'lat29',latein:'Nemo iudex in causa sua.',uebersetzung:'Niemand soll Richter in eigener Sache sein.',autor:'Rechtsgrundsatz (römisches Recht)',kontext:'Grundlegendes Prinzip der Unparteilichkeit, bis heute Basis des Ablehnungsrechts von Richtern.'},{id:'lat30',latein:'Nulla poena sine lege.',uebersetzung:'Keine Strafe ohne Gesetz.',autor:'Rechtsgrundsatz, später von Paul Johann Anselm von Feuerbach formuliert',kontext:'Fundamentales Prinzip des modernen Strafrechts – keine Bestrafung ohne vorher bestehende gesetzliche Grundlage.'},{id:'lat31',latein:'Vae victis.',uebersetzung:'Wehe den Besiegten.',autor:'Brennus (überliefert durch Livius)',kontext:'Soll der gallische Anführer Brennus 387 v. Chr. bei der Belagerung Roms gesagt haben, als er zusätzliches Gewicht auf die Waage der Tributzahlung legte.'},{id:'lat32',latein:'Rara avis.',uebersetzung:'Ein seltener Vogel.',autor:'Juvenal',kontext:'Aus den Satiren (6, 165); Bild für etwas oder jemanden Außergewöhnliches, kaum Auffindbares.'},{id:'lat33',latein:'Quod erat demonstrandum.',uebersetzung:'Was zu beweisen war.',autor:'Euklid (griechisch), lateinische Standardformel',kontext:'Klassischer Abschluss eines mathematischen oder logischen Beweises.'},{id:'lat34',latein:'Ex nihilo nihil fit.',uebersetzung:'Aus nichts entsteht nichts.',autor:'Parmenides / Lukrez',kontext:'Grundsatz antiker Naturphilosophie: Nichts kann ohne Ursache aus dem Nichts entstehen.'},{id:'lat35',latein:'Deus ex machina.',uebersetzung:'Gott aus der Maschine.',autor:'Griechisches Theater, lateinisch überliefert',kontext:'Bezeichnet eine unerwartete, unmotivierte Lösung eines Konflikts – ursprünglich der herabgelassene Gott am Ende antiker Dramen.'},{id:'lat36',latein:'Panta rhei (gr.), omnia fluunt.',uebersetzung:'Alles fließt.',autor:'Heraklit (griechisch), lateinische Übertragung',kontext:'Kernsatz der heraklitischen Philosophie des ständigen Wandels.'},{id:'lat38',latein:'Docendo discimus.',uebersetzung:'Durch Lehren lernen wir.',autor:'Seneca',kontext:'Aus den Epistulae Morales (Brief 7); zentrale pädagogische Einsicht.'},{id:'lat39',latein:'Non scholae, sed vitae discimus.',uebersetzung:'Nicht für die Schule, sondern für das Leben lernen wir.',autor:'Seneca',kontext:'Aus den Epistulae Morales (Brief 106) – ursprünglich als Kritik gemeint, dass Gelehrte oft nur für die Schule statt fürs Leben lernen.'},{id:'lat40',latein:'Sapere aude.',uebersetzung:'Habe Mut, dich deines eigenen Verstandes zu bedienen.',autor:'Horaz, durch Kant zum Wahlspruch der Aufklärung gemacht',kontext:'Aus Horaz\' Episteln (1, 2, 40); Kant machte den Satz 1784 zum Motto der Aufklärung.'},{id:'lat41',latein:'Corruptio optimi pessima.',uebersetzung:'Die Verderbnis des Besten ist das Schlimmste.',autor:'Scholastische Tradition',kontext:'Mittelalterlicher Grundsatz: Je höher das ursprüngliche Gut, desto schlimmer seine Verfälschung.'},{id:'lat42',latein:'Divide et impera.',uebersetzung:'Teile und herrsche.',autor:'Politisches Prinzip, oft Philipp II. von Makedonien oder Machiavelli zugeschrieben',kontext:'Strategie, Gegner durch gezielte Spaltung zu schwächen, statt sie geschlossen zu bekämpfen.'},{id:'lat43',latein:'Do ut des.',uebersetzung:'Ich gebe, damit du gibst.',autor:'Römisches Vertrags- und Opferrecht',kontext:'Prinzip der Gegenseitigkeit – Grundlage vieler sozialer und rechtlicher Tauschbeziehungen.'},{id:'lat44',latein:'Habeas corpus.',uebersetzung:'Du sollst den Körper haben.',autor:'Englisches Recht (lateinischer Rechtsterminus)',kontext:'Grundrecht auf Überprüfung der Rechtmäßigkeit einer Freiheitsentziehung vor Gericht.'},{id:'lat45',latein:'Ceteris paribus.',uebersetzung:'Unter sonst gleichen Bedingungen.',autor:'Wissenschaftliche/ökonomische Fachsprache',kontext:'Klausel, um einen Zusammenhang isoliert zu betrachten, während alle anderen Faktoren konstant gehalten werden.'},{id:'lat46',latein:'Modus vivendi.',uebersetzung:'Art zu leben / vorläufige Übereinkunft.',autor:'Diplomatische Fachsprache',kontext:'Bezeichnet eine pragmatische Übereinkunft zwischen Parteien, die grundsätzliche Differenzen (vorerst) offenlässt.'},{id:'lat48',latein:'Verba volant, scripta manent.',uebersetzung:'Worte fliegen, Geschriebenes bleibt.',autor:'Lateinisches Sprichwort',kontext:'Betont die Verlässlichkeit schriftlicher gegenüber mündlicher Zusagen.'},{id:'lat49',latein:'Omnia mea mecum porto.',uebersetzung:'Alles, was mein ist, trage ich bei mir.',autor:'Cicero (überliefert, ursprünglich Bias von Priene zugeschrieben)',kontext:'Stoisches Motiv: Wahrer Besitz ist innerer, nicht äußerer Natur – Weisheit und Charakter kann niemand rauben.'},{id:'lat50',latein:'Nihil novi sub sole.',uebersetzung:'Nichts Neues unter der Sonne.',autor:'Vulgata, Buch Kohelet 1,9',kontext:'Lateinische Fassung eines Satzes aus dem biblischen Buch Kohelet/Prediger.'},{id:'lat51',latein:'Dulce et decorum est pro patria mori.',uebersetzung:'Süß und ehrenvoll ist es, für das Vaterland zu sterben.',autor:'Horaz',kontext:'Aus den Oden (3,2,13); später von Wilfred Owen in seinem berühmten Antikriegsgedicht bitter ironisch aufgegriffen und als \'die alte Lüge\' bezeichnet.'},{id:'lat52',latein:'O tempora, o mores!',uebersetzung:'Oh Zeiten, oh Sitten!',autor:'Cicero',kontext:'Aus der ersten Catilinarischen Rede (63 v. Chr.); Ausdruck der Empörung über den moralischen Verfall der eigenen Zeit.'},{id:'lat53',latein:'Homo sum, humani nihil a me alienum puto.',uebersetzung:'Ich bin ein Mensch, nichts Menschliches ist mir fremd.',autor:'Terenz',kontext:'Aus der Komödie „Heautontimorumenos"; oft als Ausdruck universeller Empathie und Menschlichkeit zitiert.'},{id:'lat54',latein:'Timeo Danaos et dona ferentes.',uebersetzung:'Ich fürchte die Griechen, auch wenn sie Geschenke bringen.',autor:'Vergil',kontext:'Aus der Aeneis (2,49); Warnung des Laokoon vor dem Trojanischen Pferd — Ursprung der Redewendung \'Griechisches Geschenk\'.'},{id:'lat55',latein:'Fiat iustitia, ruat caelum.',uebersetzung:'Es geschehe Gerechtigkeit, auch wenn der Himmel einstürzt.',autor:'Zugeschrieben u. a. Ferdinand I.',kontext:'Rechtsphilosophischer Grundsatz: Gerechtigkeit darf nicht den Konsequenzen geopfert werden.'},{id:'lat56',latein:'Summum ius, summa iniuria.',uebersetzung:'Höchstes Recht, höchstes Unrecht.',autor:'Cicero',kontext:'Aus \'De Officiis\' (1,33); Warnung davor, dass allzu buchstabengetreue Rechtsanwendung selbst zu Unrecht führen kann.'},{id:'lat57',latein:'Historia magistra vitae est.',uebersetzung:'Die Geschichte ist die Lehrmeisterin des Lebens.',autor:'Cicero',kontext:'Aus \'De Oratore\' (2,36); Grundgedanke, dass sich aus der Vergangenheit Lehren für die Gegenwart ziehen lassen.'},{id:'lat58',latein:'Scientia potentia est.',uebersetzung:'Wissen ist Macht.',autor:'Francis Bacon (lateinische Formulierung)',kontext:'Kernsatz der Bacon\'schen Philosophie: Erkenntnis der Natur verschafft dem Menschen Handlungsmacht über sie.'},{id:'lat59',latein:'Primum non nocere.',uebersetzung:'Zuerst nicht schaden.',autor:'Medizinische Tradition, oft Hippokrates zugeschrieben',kontext:'Grundprinzip medizinischer Ethik, tatsächlich erst deutlich später in dieser Formulierung belegt, aber im Geiste des Hippokratischen Eids.'},{id:'lat60',latein:'Si tacuisses, philosophus mansisses.',uebersetzung:'Hättest du geschwiegen, wärst du Philosoph geblieben.',autor:'Boethius',kontext:'Aus \'De consolatione philosophiae\'; Erinnerung daran, dass unüberlegtes Reden auch kluge Menschen töricht wirken lassen kann.'},{id:'lat61',latein:'Manus manum lavat.',uebersetzung:'Eine Hand wäscht die andere.',autor:'Seneca (u. a. in den Apocolocyntosis)',kontext:'Sprichwörtliche Beschreibung wechselseitiger Gefälligkeiten.'},{id:'lat62',latein:'De mortuis nihil nisi bonum.',uebersetzung:'Über die Toten nur Gutes.',autor:'Zugeschrieben Chilon von Sparta (überliefert bei Diogenes Laertius)',kontext:'Gesellschaftliche Konvention, Verstorbene nicht schlechtzureden.'},{id:'lat63',latein:'De gustibus non est disputandum.',uebersetzung:'Über Geschmack lässt sich nicht streiten.',autor:'Lateinisches Sprichwort',kontext:'Klassischer Grundsatz zur Subjektivität ästhetischer Urteile.'},{id:'lat64',latein:'Consuetudinis magna vis est.',uebersetzung:'Die Macht der Gewohnheit ist groß.',autor:'Cicero',kontext:'Aus \'Pro Milone\'; Beobachtung, wie stark Gewohnheiten menschliches Verhalten prägen.'},{id:'lat65',latein:'Nulla dies sine linea.',uebersetzung:'Kein Tag ohne einen (Feder-)Strich.',autor:'Plinius der Ältere (über den Maler Apelles)',kontext:'Motto für tägliche disziplinierte Übung, oft von Künstlern und Schriftstellern als Arbeitsgrundsatz zitiert.'},{id:'lat66',latein:'Natura non facit saltus.',uebersetzung:'Die Natur macht keine Sprünge.',autor:'Wissenschaftliche Tradition (u. a. Linné, Leibniz)',kontext:'Grundsatz, dass Veränderungen in der Natur graduell statt sprunghaft erfolgen — von Darwin aufgegriffen, später durch die Genetik relativiert.'},{id:'lat67',latein:'Exceptio probat regulam.',uebersetzung:'Die Ausnahme bestätigt die Regel.',autor:'Juristische Tradition',kontext:'Ursprünglich juristisch gemeint: Eine ausdrücklich genannte Ausnahme bestätigt, dass für alle anderen Fälle die Regel gilt — häufig missverstanden als \'Ausnahmen beweisen, dass Regeln stimmen\'.'},{id:'lat68',latein:'Qui tacet consentire videtur.',uebersetzung:'Wer schweigt, scheint zuzustimmen.',autor:'Rechtsgrundsatz, u. a. Papst Bonifaz VIII. zugeschrieben',kontext:'Rechtsprinzip mit wichtiger Einschränkung: Gilt nur, wo tatsächlich eine Pflicht zum Widerspruch bestand.'},{id:'lat69',latein:'Res, non verba.',uebersetzung:'Taten, nicht Worte.',autor:'Lateinisches Sprichwort',kontext:'Betont, dass Handlungen mehr zählen als Ankündigungen.'},{id:'lat70',latein:'Ubi bene, ibi patria.',uebersetzung:'Wo es einem gut geht, da ist die Heimat.',autor:'Antikes Sprichwort (u. a. bei Cicero angedeutet)',kontext:'Kosmopolitischer Gedanke: Heimat ist nicht zwingend an den Geburtsort gebunden.'},{id:'lat71',latein:'Vivere militare est.',uebersetzung:'Leben heißt kämpfen.',autor:'Seneca',kontext:'Aus den Epistulae Morales (Brief 96); stoisches Bild des Lebens als fortwährende Herausforderung, der man sich stellen muss.'},{id:'lat72',latein:'Aut viam inveniam aut faciam.',uebersetzung:'Ich werde einen Weg finden oder einen bahnen.',autor:'Hannibal (überliefert)',kontext:'Soll Hannibal beim Alpenübergang gesagt haben — Sinnbild unbedingter Entschlossenheit.'},{id:'lat73',latein:'Ora et labora.',uebersetzung:'Bete und arbeite.',autor:'Sinngemäß benediktinische Klosterregel',kontext:'Leitspruch benediktinischer Klöster zur Verbindung von geistlichem und tätigem Leben — als wörtliches Zitat der Regel Benedikts nicht belegt, aber deren Geist zusammenfassend.'},{id:'lat74',latein:'Ignis aurum probat.',uebersetzung:'Feuer prüft das Gold.',autor:'Antikes Sprichwort, stoisch geprägt (vgl. Seneca)',kontext:'Bild dafür, dass sich wahrer Charakter erst in schwierigen Situationen zeigt.'},{id:'lat75',latein:'Multum, non multa.',uebersetzung:'Viel (in der Tiefe), nicht Vieles.',autor:'Plinius der Jüngere',kontext:'Grundsatz für vertiefte Lektüre statt oberflächlicher Vielleserei.'}];export const RHETORISCHE_SCHATZKISTE=[{id:'s1',typ:'satzbaustein',titel:'Einwand elegant einleiten',formulierung:'So berechtigt der Einwand ist, so sehr lohnt sich doch ein zweiter Blick auf...',wirkung:'Entschärft Widerspruch, ohne die Gegenposition abzuwerten, bevor man die eigene Sicht darlegt.'},{id:'s2',typ:'satzbaustein',titel:'Zustimmung mit Präzisierung verbinden',formulierung:'Dem stimme ich im Grundsatz zu, möchte aber einen Punkt präzisieren.',wirkung:'Wirkt kooperativ statt konfrontativ und öffnet trotzdem Raum für die eigene Nuance.'},{id:'s3',typ:'satzbaustein',titel:'Position pointiert zusammenfassen',formulierung:'Im Kern lässt sich das auf einen einzigen Gedanken zurückführen:',wirkung:'Signalisiert Klarheit und rhetorische Souveränität vor einer prägnanten Schlussaussage.'},{id:'s4',typ:'satzbaustein',titel:'Von Konkretem zu Allgemeinem überleiten',formulierung:'Dieses Beispiel steht stellvertretend für ein größeres Muster:',wirkung:'Klassische induktive Überleitung, die Cicero und Aristoteles in der Beweisführung nutzten.'},{id:'s5',typ:'satzbaustein',titel:'Rhetorische Frage zur Fokussierung',formulierung:'Doch was bedeutet das eigentlich konkret für uns?',wirkung:'Lenkt die Aufmerksamkeit gezielt zurück auf die praktische Konsequenz eines abstrakten Arguments.'},{id:'s6',typ:'satzbaustein',titel:'Dreiergruppe zur Verstärkung (Tricolon)',formulierung:'Es geht um Klarheit, um Konsequenz, und vor allem um Glaubwürdigkeit.',wirkung:'Die klassische Drei-Wort-Gruppe erzeugt Rhythmus und wirkt in Reden besonders einprägsam.'},{id:'s7',typ:'satzbaustein',titel:'Gegensatz zuspitzen (Antithese)',formulierung:'Nicht mehr Regeln lösen das Problem, sondern mehr Vertrauen.',wirkung:'Cicero und Kennedy nutzten diese Kontrastform, um Positionen scharf voneinander abzugrenzen.'},{id:'s8',typ:'satzbaustein',titel:'Höflich, aber bestimmt widersprechen',formulierung:'Bei allem Respekt vor dieser Sichtweise – die Faktenlage zeichnet ein anderes Bild.',wirkung:'Bewahrt den Ton, macht aber die inhaltliche Differenz unmissverständlich klar.'},{id:'s9',typ:'satzbaustein',titel:'Zum Abschluss auf den Punkt bringen',formulierung:'Am Ende bleibt eine einzige Frage entscheidend:',wirkung:'Bündelt eine längere Ausführung und bereitet eine pointierte Schlussfolgerung vor.'},{id:'s10',typ:'satzbaustein',titel:'Gemeinsamkeit vor Differenz betonen',formulierung:'Wir sind uns einig, dass X wichtig ist – die Frage ist nur, wie wir dorthin kommen.',wirkung:'Klassische Technik, um eine Diskussion konstruktiv statt konfrontativ zu rahmen.'},{id:'s11',typ:'satzbaustein',titel:'Autorität einbinden, ohne unterwürfig zu wirken',formulierung:'Wie bereits [Name/Studie] gezeigt hat, bestätigt sich hier ein bekanntes Muster.',wirkung:'Stützt die eigene Aussage durch externe Glaubwürdigkeit, ohne die eigene Position aufzugeben.'},{id:'s12',typ:'satzbaustein',titel:'Einwand vorwegnehmen (Antizipation)',formulierung:'Man könnte einwenden, dass X — doch genau das spricht eher für als gegen den Ansatz.',wirkung:'Nimmt dem Gegenüber den Überraschungseffekt und zeigt rhetorische Souveränität.'},{id:'s13',typ:'satzbaustein',titel:'Vom Kleinen zum Großen steigern (Klimax)',formulierung:'Das betrifft nicht nur unser Team, nicht nur die Abteilung, sondern das ganze Unternehmen.',wirkung:'Steigerung in drei Stufen erzeugt Dringlichkeit und wachsende Wichtigkeit.'},{id:'s14',typ:'satzbaustein',titel:'Gemeinsame Werte beschwören',formulierung:'Wenn uns eines eint, dann der Anspruch, es besser zu machen als gestern.',wirkung:'Schafft Zusammengehörigkeit, bevor eine unbequeme Botschaft folgt.'},{id:'s15',typ:'satzbaustein',titel:'Bildhafte Analogie einführen',formulierung:'Das ist, als würde man ein Loch stopfen, während das Boot bereits sinkt.',wirkung:'Macht ein abstraktes Problem sofort greifbar und einprägsam.'},{id:'s16',typ:'satzbaustein',titel:'Verantwortung übernehmen, ohne sich klein zu machen',formulierung:'Das war meine Entscheidung, und ich stehe dazu — gleichzeitig ziehe ich daraus diese Konsequenz.',wirkung:'Wirkt integer und stark zugleich, statt entweder arrogant oder unterwürfig.'},{id:'s17',typ:'satzbaustein',titel:'Dringlichkeit erzeugen',formulierung:'Je länger wir warten, desto teurer wird jede spätere Korrektur.',wirkung:'Klassische Technik, um Handlungsbedarf spürbar zu machen, ohne zu drängen.'},{id:'s18',typ:'satzbaustein',titel:'Perspektivwechsel anbieten',formulierung:'Stellen wir uns das Ganze für einen Moment aus Sicht von [Person/Gruppe] vor.',wirkung:'Öffnet neue Denkräume und wirkt kooperativ statt belehrend.'},{id:'s19',typ:'satzbaustein',titel:'Rhetorische Wiederholung (Anapher)',formulierung:'Wir wollen Klarheit. Wir wollen Verlässlichkeit. Wir wollen Ergebnisse.',wirkung:'Wiederholter Satzanfang erzeugt Rhythmus und bleibt im Gedächtnis – von Cicero bis Martin Luther King genutzt.'},{id:'s20',typ:'satzbaustein',titel:'Vom Einwand zur Brücke',formulierung:'Genau dieser Punkt zeigt, warum eine andere Lösung nötig ist.',wirkung:'Verwandelt einen kritischen Einwand elegant in ein Argument für die eigene Position.'},{id:'s21',typ:'satzbaustein',titel:'Konkrete Zahl statt vager Aussage',formulierung:'Nicht \'viele\', sondern konkret sieben von zehn Fällen zeigen dieses Muster.',wirkung:'Konkrete Zahlen wirken glaubwürdiger und überprüfbarer als vage Mengenangaben.'},{id:'s22',typ:'satzbaustein',titel:'Gesprächspartner sanft korrigieren',formulierung:'Ein wichtiger Punkt – ich würde nur eine Nuance ergänzen.',wirkung:'Vermeidet direkte Konfrontation und öffnet Raum für die eigene Präzisierung.'},{id:'s23',typ:'satzbaustein',titel:'Zusammenfassend zuspitzen',formulierung:'Kurz gesagt: [Kernaussage in einem Satz].',wirkung:'Bündelt komplexe Ausführungen und erleichtert dem Publikum, den Kern mitzunehmen.'},{id:'s24',typ:'satzbaustein',titel:'Von der Ausnahme zur Regel abgrenzen',formulierung:'Das mag im Einzelfall zutreffen, ändert aber nichts am grundsätzlichen Muster.',wirkung:'Verhindert, dass ein Gegenbeispiel die eigene Gesamtargumentation entkräftet.'},{id:'s25',typ:'satzbaustein',titel:'Einladung zur gemeinsamen Lösung',formulierung:'Lassen Sie uns gemeinsam einen Weg finden, der für beide Seiten funktioniert.',wirkung:'Signalisiert Kooperationsbereitschaft und verwandelt eine Konfrontation in ein gemeinsames Projekt.'},{id:'st1',typ:'stilmittel',name:'Anapher',definition:'Wiederholung desselben Wortes oder derselben Wortgruppe am Satz- oder Versanfang, um Rhythmus und Nachdruck zu erzeugen.',beispiel:'„Wir wollen Klarheit. Wir wollen Mut. Wir wollen Wandel."'},{id:'st2',typ:'stilmittel',name:'Antithese',definition:'Gegenüberstellung zweier gegensätzlicher Gedanken oder Begriffe zur Zuspitzung einer Aussage.',beispiel:'„Nicht mehr Regeln, sondern mehr Vertrauen."'},{id:'st3',typ:'stilmittel',name:'Rhetorische Frage',definition:'Eine Frage, auf die keine Antwort erwartet wird, weil sie bereits in sich enthalten ist – dient der Betonung.',beispiel:'„Wer würde das nicht wollen?"'},{id:'st4',typ:'stilmittel',name:'Metapher',definition:'Bildhafte Übertragung eines Begriffs aus einem Bereich auf einen anderen, um abstrakte Sachverhalte zu veranschaulichen.',beispiel:'„Das Projekt steht auf wackligen Beinen."'},{id:'st5',typ:'stilmittel',name:'Hyperbel',definition:'Bewusste Übertreibung zur Verstärkung einer Aussage – wird im Kontext meist nicht wörtlich genommen.',beispiel:'„Das habe ich dir schon tausendmal erklärt."'},{id:'st6',typ:'stilmittel',name:'Chiasmus',definition:'Überkreuzstellung zweier Satzteile in umgekehrter Reihenfolge, oft mit einprägsamem Effekt.',beispiel:'„Nicht das Amt macht den Menschen, sondern der Mensch das Amt."'},{id:'st7',typ:'stilmittel',name:'Litotes',definition:'Bejahung durch doppelte Verneinung – wirkt zurückhaltender und oft ironischer als eine direkte Aussage.',beispiel:'„Das war nicht unklug von dir." (= das war klug)'},{id:'st8',typ:'stilmittel',name:'Euphemismus',definition:'Beschönigende Umschreibung eines unangenehmen oder heiklen Sachverhalts.',beispiel:'„Das Unternehmen musste sich von Personal trennen." (statt: entlassen)'},{id:'st9',typ:'stilmittel',name:'Parallelismus',definition:'Wiederholung derselben grammatischen Struktur in aufeinanderfolgenden Sätzen oder Satzteilen zur Betonung.',beispiel:'„Der eine gibt auf, der andere gibt nicht auf."'},{id:'st10',typ:'stilmittel',name:'Klimax',definition:'Stufenweise Steigerung einer Aussage bis zu ihrem Höhepunkt.',beispiel:'„Er kam, sah, und siegte."'},{id:'st11',typ:'stilmittel',name:'Ironie',definition:'Aussage, die das Gegenteil dessen meint, was wörtlich gesagt wird – oft an Tonfall oder Kontext erkennbar.',beispiel:'„Na, das ist ja mal wieder bestens gelaufen." (bei einem Misserfolg)'},{id:'st12',typ:'stilmittel',name:'Ellipse',definition:'Bewusstes Weglassen von Satzteilen, die aus dem Kontext erschließbar sind – wirkt prägnant und schlagkräftig.',beispiel:'„Je mehr Mut, desto mehr Erfolg." (statt: je mehr Mut man hat, desto mehr Erfolg hat man)'},{id:'st13',typ:'stilmittel',name:'Alliteration',definition:'Gleicher Anlaut mehrerer aufeinanderfolgender Wörter – erzeugt Klangwirkung und Einprägsamkeit.',beispiel:'„Mit Mut und Motivation zum Meilenstein."'},{id:'st14',typ:'stilmittel',name:'Anadiplose',definition:'Wiederholung des letzten Wortes eines Satzes am Anfang des nächsten Satzes – erzeugt eine Kettenwirkung.',beispiel:'„Aus Fleiß wird Erfolg. Erfolg wiederum schafft Vertrauen."'},{id:'st15',typ:'stilmittel',name:'Praeteritio',definition:'Man kündigt an, etwas nicht zu erwähnen – und erwähnt es dadurch gerade doch, oft mit besonderem Nachdruck.',beispiel:'„Ich will gar nicht davon anfangen, wie oft dieser Fehler schon passiert ist."'},{id:'fw1',typ:'fremdwort',einfach:'das berührt mich nicht',fremdwort:'tangieren',beispiel:'Das tangiert mich nicht.',hinweis:'Klingt distanzierter und sachlicher als die Alltagsformulierung.'},{id:'fw2',typ:'fremdwort',einfach:'der Zusammenhang zwischen Wörtern und Bedeutung',fremdwort:'Semantik',beispiel:'Hier geht es um die Semantik des Begriffs, nicht nur um seine Definition.',hinweis:'Wirkt fachlich präzise, besonders in Diskussionen über Wortbedeutungen.'},{id:'fw3',typ:'fremdwort',einfach:'auf den Menschen bezogen / menschenkundlich',fremdwort:'anthropologisch',beispiel:'Das lässt sich anthropologisch begründen: Menschen suchen seit jeher nach Zugehörigkeit.',hinweis:'Eignet sich, um eine Aussage über menschliches Verhalten wissenschaftlicher wirken zu lassen.'},{id:'fw4',typ:'fremdwort',einfach:'offensichtlich, klar erkennbar',fremdwort:'evident',beispiel:'Der Vorteil ist evident, sobald man die Zahlen betrachtet.',hinweis:'Wirkt sachlicher als \'offensichtlich\', besonders in Argumentationen.'},{id:'fw5',typ:'fremdwort',einfach:'heikel, unsicher, gefährdet',fremdwort:'prekär',beispiel:'Die Lage ist prekär, aber nicht aussichtslos.',hinweis:'Klingt differenzierter als \'schwierig\' oder \'schlecht\'.'},{id:'fw6',typ:'fremdwort',einfach:'veraltet, nicht mehr gültig',fremdwort:'obsolet',beispiel:'Dieses Vorgehen ist inzwischen obsolet.',hinweis:'Wirkt entschiedener und gebildeter als \'überholt\'.'},{id:'fw7',typ:'fremdwort',einfach:'erfahren, fachkundig',fremdwort:'versiert',beispiel:'Sie ist versiert im Umgang mit schwierigen Kunden.',hinweis:'Eine elegante Alternative zu \'erfahren\' oder \'gut darin\'.'},{id:'fw8',typ:'fremdwort',einfach:'nachvollziehbar, einleuchtend',fremdwort:'plausibel',beispiel:'Das Argument klingt plausibel, verdient aber eine genauere Prüfung.',hinweis:'Wirkt abwägender als ein einfaches \'stimmt\' oder \'macht Sinn\'.'},{id:'fw9',typ:'fremdwort',einfach:'stimmig, übereinstimmend',fremdwort:'kongruent',beispiel:'Die Botschaft ist kongruent mit dem, was das Unternehmen tatsächlich lebt.',hinweis:'Besonders wirkungsvoll, wenn es um Übereinstimmung zwischen Wort und Handlung geht.'},{id:'fw10',typ:'fremdwort',einfach:'zwiespältig, mit gemischten Gefühlen',fremdwort:'ambivalent',beispiel:'Ich bin ambivalent, was diese Entscheidung angeht.',hinweis:'Klingt reflektierter als \'ich bin mir nicht sicher\'.'},{id:'fw11',typ:'fremdwort',einfach:'entschieden, klar festgelegt',fremdwort:'dezidiert',beispiel:'Er vertrat eine dezidiert andere Meinung.',hinweis:'Verstärkt eine klare Position, ohne aggressiv zu wirken.'},{id:'fw12',typ:'fremdwort',einfach:'die Lehre vom Wissen und seiner Begründung',fremdwort:'Epistemologie',beispiel:'Das ist letztlich eine epistemologische Frage: Woher wissen wir das überhaupt?',hinweis:'Wirkt gebildet in Diskussionen über Wissen, Beweise oder Quellen.'},{id:'fw13',typ:'fremdwort',einfach:'das grundlegende Denkmuster / Vorbildmodell einer Zeit',fremdwort:'Paradigma',beispiel:'Wir brauchen hier einen echten Paradigmenwechsel, keine kleine Anpassung.',hinweis:'Signalisiert, dass es um eine grundsätzliche, nicht nur oberflächliche Veränderung geht.'},{id:'fw14',typ:'fremdwort',einfach:'das Gespräch, der Diskurs über ein Thema',fremdwort:'Diskurs',beispiel:'Der öffentliche Diskurs zu diesem Thema hat sich in den letzten Jahren verschoben.',hinweis:'Hebt eine Debatte auf eine gesellschaftliche, überindividuelle Ebene.'},{id:'fw15',typ:'fremdwort',einfach:'was aus etwas folgt, mitgemeint ist',fremdwort:'Implikation',beispiel:'Diese Entscheidung hat weitreichende Implikationen, die wir bedenken sollten.',hinweis:'Klingt präziser als \'Folgen\' und betont das indirekt Mitgemeinte.'},{id:'fw16',typ:'fremdwort',einfach:'die Zweiteilung, der scharfe Gegensatz',fremdwort:'Dichotomie',beispiel:'Die Dichotomie zwischen Theorie und Praxis lässt sich hier gut beobachten.',hinweis:'Wirkt analytisch, wenn ein klarer Gegensatz benannt werden soll.'},{id:'fw17',typ:'fremdwort',einfach:'eine als wahr vorausgesetzte Grundannahme',fremdwort:'Prämisse',beispiel:'Die Prämisse dieses Arguments teile ich nicht.',hinweis:'Präziser als \'Grundannahme\' und signalisiert argumentative Schärfe.'},{id:'fw18',typ:'fremdwort',einfach:'die innere Stimmigkeit, Widerspruchsfreiheit',fremdwort:'Kohärenz',beispiel:'Der Argumentation fehlt es an Kohärenz.',hinweis:'Klingt fachlicher als \'das passt nicht zusammen\'.'},{id:'fw19',typ:'fremdwort',einfach:'eine feine Bedeutungsabstufung',fremdwort:'Nuance',beispiel:'Da gibt es eine wichtige Nuance, die man nicht übersehen sollte.',hinweis:'Signalisiert Differenzierungsvermögen statt Schwarz-Weiß-Denken.'},{id:'fw20',typ:'fremdwort',einfach:'die mitschwingende Nebenbedeutung eines Wortes',fremdwort:'Konnotation',beispiel:'Dieses Wort hat eine negative Konnotation, die wir vermeiden sollten.',hinweis:'Nützlich, um über Wortwahl und Wirkung präzise zu sprechen.'},{id:'st16',typ:'stilmittel',name:'Zeugma',definition:'Ein Wort (meist ein Verb) bezieht sich grammatisch korrekt, aber inhaltlich überraschend auf zwei unterschiedliche Satzteile zugleich.',beispiel:'„Er verlor sein Geld und seine Fassung."'},{id:'st17',typ:'stilmittel',name:'Oxymoron',definition:'Verbindung zweier sich scheinbar widersprechender Begriffe zu einer pointierten Einheit.',beispiel:'„Eine beredte Stille lag über dem Raum."'},{id:'st18',typ:'stilmittel',name:'Apostrophe (Anrede)',definition:'Direkte, oft emotionale Anrede einer Person, Gruppe oder eines abstrakten Konzepts, um Nähe und Dringlichkeit zu erzeugen.',beispiel:'„Liebe Kolleginnen und Kollegen, genau jetzt zählt jede Entscheidung."'},{id:'st19',typ:'stilmittel',name:'Symploke',definition:'Kombination aus Anapher (gleicher Satzanfang) und Epipher (gleiches Satzende) in aufeinanderfolgenden Sätzen.',beispiel:'„Wir haben investiert, weil wir an die Zukunft glauben. Wir haben gebaut, weil wir an die Zukunft glauben."'},{id:'st20',typ:'stilmittel',name:'Epipher',definition:'Wiederholung desselben Wortes oder derselben Wortgruppe am Ende aufeinanderfolgender Sätze.',beispiel:'„Der Kunde hat recht. Der Chef hat recht. Am Ende hat immer irgendjemand recht."'},{id:'st21',typ:'stilmittel',name:'Hendiadyoin',definition:'Ausdruck eines einzigen Gedankens durch zwei gleichgeordnete Begriffe statt durch ein Adjektiv und ein Substantiv.',beispiel:'„Mit Zittern und Zagen betrat er den Raum." (statt: ängstlich)'},{id:'st22',typ:'stilmittel',name:'Correctio (Selbstkorrektur)',definition:'Bewusste rhetorische Selbstkorrektur, um eine Aussage nachträglich zu verstärken oder zu präzisieren.',beispiel:'„Das war ein Fehler — nein, mehr als das: ein Versäumnis."'},{id:'st23',typ:'stilmittel',name:'Aposiopese',definition:'Bewusster Satzabbruch, der dem Zuhörer überlässt, den Gedanken selbst zu Ende zu denken — oft wirkungsvoller als das ausgesprochene Wort.',beispiel:'„Wenn das so weitergeht, dann..." (Pause, ohne den Satz zu beenden)'},{id:'st24',typ:'stilmittel',name:'Polysyndeton',definition:'Häufung von Bindewörtern (meist \'und\'), um eine Aufzählung als überwältigend oder ununterbrochen wirken zu lassen.',beispiel:'„Wir haben geplant und gebaut und getestet und geliefert."'},{id:'st25',typ:'stilmittel',name:'Asyndeton',definition:'Bewusster Verzicht auf Bindewörter in einer Aufzählung, um Tempo und Wucht zu erzeugen.',beispiel:'„Wir kamen, sahen, siegten."'},{id:'st26',typ:'stilmittel',name:'Personifikation',definition:'Vermenschlichung eines abstrakten Begriffs oder einer Sache, um sie greifbarer zu machen.',beispiel:'„Die Zeit heilt Wunden."'},{id:'st27',typ:'stilmittel',name:'Klimax (Steigerung) vs. Antiklimax',definition:'Während die Klimax stufenweise steigert, bricht die Antiklimax den Höhepunkt bewusst mit einer Enttäuschung — oft für humorvolle oder entlarvende Effekte.',beispiel:'„Er kämpfte für Freiheit, Gerechtigkeit — und einen Parkplatz direkt vor der Tür."'},{id:'st28',typ:'stilmittel',name:'Rhetorischer Vergleich (Similes)',definition:'Explizite Gegenüberstellung zweier Dinge mit \'wie\' oder \'als\', um eine Aussage plastischer zu machen.',beispiel:'„Die Diskussion verlief wie ein Tennismatch ohne Netz."'},{id:'st29',typ:'stilmittel',name:'Diminutio (Verkleinerung/Untertreibung)',definition:'Bewusstes Herunterspielen eines Sachverhalts, oft mit ironischem Unterton, um Größe gerade durch Kontrast zu betonen.',beispiel:'„Ein kleines Detail: Wir haben den Umsatz verdoppelt."'},{id:'st30',typ:'stilmittel',name:'Praesens historicum',definition:'Verwendung der Gegenwartsform für vergangene Ereignisse, um Lebendigkeit und Unmittelbarkeit zu erzeugen.',beispiel:'„Cäsar überquert den Rubikon — und Rom hält den Atem an."'},{id:'fw21',typ:'fremdwort',einfach:'grundlegend, die Grundlage betreffend',fremdwort:'fundamental',beispiel:'Das ist ein fundamentaler Unterschied zwischen beiden Ansätzen.',hinweis:'Klingt gewichtiger als \'grundlegend\' und betont die Tragweite.'},{id:'fw22',typ:'fremdwort',einfach:'genau, sorgfältig durchdacht',fremdwort:'präzise / akribisch',beispiel:'Er hat die Zahlen akribisch geprüft.',hinweis:'\'Akribisch\' wirkt fachlicher und wertschätzender als \'genau\'.'},{id:'fw23',typ:'fremdwort',einfach:'widersprüchlich in sich',fremdwort:'paradox',beispiel:'Es ist paradox, dass mehr Auswahl oft zu weniger Zufriedenheit führt.',hinweis:'Nützlich, um einen überraschenden inneren Widerspruch zu benennen.'},{id:'fw24',typ:'fremdwort',einfach:'auf Erfahrung beruhend, durch Beobachtung belegt',fremdwort:'empirisch',beispiel:'Das lässt sich empirisch belegen, nicht nur theoretisch behaupten.',hinweis:'Signalisiert wissenschaftliche Sorgfalt statt bloßer Meinung.'},{id:'fw25',typ:'fremdwort',einfach:'alles durchdringend, umfassend',fremdwort:'allumfassend / omnipräsent',beispiel:'Die Unsicherheit war in diesem Quartal geradezu omnipräsent.',hinweis:'Wirkt eindrucksvoller als \'überall\' und betont die Intensität.'},{id:'fw26',typ:'fremdwort',einfach:'unabhängig, sich selbst genügend',fremdwort:'autonom',beispiel:'Das Team agiert inzwischen weitgehend autonom.',hinweis:'Klingt professioneller als \'selbstständig\'.'},{id:'fw27',typ:'fremdwort',einfach:'zusammenhängend, stimmig aufgebaut',fremdwort:'kohärent',beispiel:'Die Argumentation ist kohärent, auch wenn sie unbequem ist.',hinweis:'Präziser als \'schlüssig\', besonders in analytischen Kontexten.'},{id:'fw28',typ:'fremdwort',einfach:'allgemeingültig, nicht an Einzelfälle gebunden',fremdwort:'universell',beispiel:'Dieses Prinzip lässt sich universell anwenden.',hinweis:'Wirkt anspruchsvoller als \'überall gültig\'.'},{id:'fw29',typ:'fremdwort',einfach:'auf Annahmen beruhend, hypothetisch angenommen',fremdwort:'spekulativ',beispiel:'Das ist zum jetzigen Zeitpunkt noch spekulativ.',hinweis:'Signalisiert Zurückhaltung, ohne unsicher zu wirken.'},{id:'fw30',typ:'fremdwort',einfach:'zeitlich vor etwas anderem, vorausgehend',fremdwort:'antizipatorisch / vorausschauend',beispiel:'Wir handeln bewusst antizipatorisch, nicht reaktiv.',hinweis:'Betont strategisches, vorausschauendes Denken.'},{id:'fw31',typ:'fremdwort',einfach:'sich gegenseitig bedingend / ergänzend',fremdwort:'komplementär',beispiel:'Beide Ansätze sind komplementär, nicht konkurrierend.',hinweis:'Präzisiert, dass zwei Dinge sich sinnvoll ergänzen statt sich auszuschließen.'},{id:'fw32',typ:'fremdwort',einfach:'aus mehreren Elementen bestehend, vielschichtig',fremdwort:'komplex / multidimensional',beispiel:'Das Problem ist multidimensional und lässt sich nicht auf eine Ursache reduzieren.',hinweis:'Wirkt differenzierter als ein simples \'kompliziert\'.'},{id:'fw33',typ:'fremdwort',einfach:'auf das Wesentliche bezogen',fremdwort:'essenziell',beispiel:'Das ist essenziell für den langfristigen Erfolg.',hinweis:'Stärker und gewichtiger als \'wichtig\'.'},{id:'fw34',typ:'fremdwort',einfach:'sich ständig wiederholend, wiederkehrend',fremdwort:'zyklisch / rekurrent',beispiel:'Dieses Muster tritt rekurrent auf, nicht nur einmalig.',hinweis:'Klingt fachlicher als \'kommt immer wieder vor\'.'},{id:'fw35',typ:'fremdwort',einfach:'durch Vernunft, nicht durch Gefühl bestimmt',fremdwort:'rational',beispiel:'Die Entscheidung war rein rational, keine Bauchentscheidung.',hinweis:'Betont bewusste Abwägung gegenüber Emotion.'},{id:'fw36',typ:'fremdwort',einfach:'aus dem Zusammenhang gerissen, unabhängig betrachtet',fremdwort:'isoliert / dekontextualisiert',beispiel:'Diese Zahl wirkt isoliert betrachtet dramatisch, im Kontext relativiert sie sich.',hinweis:'Wirkt analytisch geschult, besonders bei Datenkritik.'},{id:'fw37',typ:'fremdwort',einfach:'sich selbst widersprechend',fremdwort:'inkonsistent',beispiel:'Die Argumentation ist an dieser Stelle inkonsistent.',hinweis:'Präziser und sachlicher als \'das passt nicht zusammen\'.'},{id:'fw38',typ:'fremdwort',einfach:'zugrunde liegend, nicht offensichtlich sichtbar',fremdwort:'latent',beispiel:'Der Konflikt war schon lange latent vorhanden, bevor er offen ausbrach.',hinweis:'Nützlich, um verborgene, noch nicht akute Zustände zu beschreiben.'},{id:'fw39',typ:'fremdwort',einfach:'auf Wechselwirkung beruhend',fremdwort:'interdependent',beispiel:'Die Abteilungen sind interdependent, Entscheidungen wirken sich gegenseitig aus.',hinweis:'Klingt systemischer als \'voneinander abhängig\'.'},{id:'fw40',typ:'fremdwort',einfach:'abschließend, endgültig festgelegt',fremdwort:'definitiv / final',beispiel:'Das ist noch nicht definitiv entschieden.',hinweis:'Wirkt entschiedener als ein einfaches \'sicher\'.'},{id:'fw41',typ:'fremdwort',einfach:'überzeugend durch innere Logik',fremdwort:'kohärent-plausibel / stringent',beispiel:'Die Argumentation ist stringent aufgebaut.',hinweis:'Betont die logische Durchgängigkeit einer Argumentationskette.'},{id:'fw42',typ:'fremdwort',einfach:'der Wirklichkeit entsprechend, sachlich richtig',fremdwort:'faktisch',beispiel:'Faktisch stimmt das nicht, auch wenn es plausibel klingt.',hinweis:'Trennt scharf zwischen Meinung und belegbarer Tatsache.'},{id:'fw43',typ:'fremdwort',einfach:'zeitlich begrenzt, vorübergehend',fremdwort:'temporär / transient',beispiel:'Das ist eine temporäre Lösung, keine dauerhafte.',hinweis:'Präziser als \'vorübergehend\' in formellen Kontexten.'},{id:'fw44',typ:'fremdwort',einfach:'auf das Ganze bezogen, nicht auf Einzelteile',fremdwort:'holistisch',beispiel:'Wir sollten das Problem holistisch betrachten, nicht nur einen Teilaspekt.',hinweis:'Signalisiert Systemdenken statt Silo-Denken.'},{id:'fw45',typ:'fremdwort',einfach:'von außen auferlegt, nicht selbst gewählt',fremdwort:'extrinsisch (Gegenteil: intrinsisch)',beispiel:'Die Motivation war eher extrinsisch als intrinsisch.',hinweis:'Wichtiges Begriffspaar in Führungs- und Motivationsgesprächen.'},{id:'fw46',typ:'fremdwort',einfach:'in sich schlüssig, nicht widersprüchlich',fremdwort:'konsistent',beispiel:'Die Preisgestaltung sollte über alle Standorte konsistent sein.',hinweis:'Klingt professioneller als \'einheitlich\'.'},{id:'fw47',typ:'fremdwort',einfach:'stark ausgeprägt, deutlich hervortretend',fremdwort:'ausgeprägt / signifikant',beispiel:'Der Unterschied ist statistisch signifikant.',hinweis:'Besonders wirkungsvoll in Verbindung mit Daten und Zahlen.'},{id:'fw48',typ:'fremdwort',einfach:'auf Ursache und Wirkung bezogen',fremdwort:'kausal',beispiel:'Der Zusammenhang ist kausal, nicht nur zufällig.',hinweis:'Wichtige Unterscheidung, um Korrelation von echter Ursache abzugrenzen.'},{id:'fw49',typ:'fremdwort',einfach:'sich wandelnd, nicht starr',fremdwort:'dynamisch',beispiel:'Der Markt ist dynamisch, unsere Strategie muss es auch sein.',hinweis:'Wirkt moderner und agiler als \'sich verändernd\'.'},{id:'fw50',typ:'fremdwort',einfach:'dem eigentlichen Zweck entsprechend, sinnvoll',fremdwort:'funktional / zweckmäßig',beispiel:'Die Lösung ist funktional, auch wenn sie nicht elegant ist.',hinweis:'Nützlich, um Pragmatismus von Perfektionismus abzugrenzen.'},{id:'fw51',typ:'fremdwort',einfach:'auf mehrere Arten deutbar, uneindeutig',fremdwort:'mehrdeutig / ambig',beispiel:'Die Formulierung ist ambig und sollte präzisiert werden.',hinweis:'Klingt fachlicher als \'unklar\' und signalisiert linguistisches Bewusstsein.'},{id:'fw52',typ:'fremdwort',einfach:'in seiner Art einzigartig, unvergleichlich',fremdwort:'singulär',beispiel:'Dieser Fall ist singulär, keine Blaupause für andere Entscheidungen.',hinweis:'Betont die Einmaligkeit eines Falls gegenüber verallgemeinerbaren Mustern.'},{id:'fw53',typ:'fremdwort',einfach:'bewusst herbeigeführt, nicht zufällig',fremdwort:'intendiert',beispiel:'War das Ergebnis intendiert oder ein Nebeneffekt?',hinweis:'Präzise Unterscheidung zwischen Absicht und Zufall.'},{id:'fw54',typ:'fremdwort',einfach:'auf das Innere, Wesentliche bezogen',fremdwort:'intrinsisch',beispiel:'Die Motivation dafür war rein intrinsisch.',hinweis:'Gegenstück zu \'extrinsisch\' — beschreibt innere statt äußere Antriebe.'},{id:'fw55',typ:'fremdwort',einfach:'sich gegenseitig ausschließend',fremdwort:'exklusiv / sich gegenseitig ausschließend',beispiel:'Die beiden Optionen sind nicht exklusiv, man kann durchaus beide wählen.',hinweis:'Nützlich in Entscheidungssituationen, um Optionen sauber abzugrenzen.'}];export const CHARISMA_UEBUNGEN=[{id:'c1',titel:'Die bewusste Pause',hintergrund:'Wirkungsvolle Redner sprechen langsamer und pausieren häufiger, als es sich im ersten Moment richtig anfühlt — Stille signalisiert Souveränität, hektisches Sprechen signalisiert Nervosität.',schritte:['Formuliere einen wichtigen Satz für dein nächstes Gespräch oder deine nächste Präsentation.','Sprich ihn laut, und lege nach der Kernaussage bewusst eine Pause von 2–3 Sekunden ein, bevor du weitersprichst.','Beobachte, wie ungewohnt lang sich die Pause anfühlt – für Zuhörer wirkt sie meist kürzer und souveräner, als du denkst.']},{id:'c2',titel:'Tricolon: Die Kraft der Drei',hintergrund:'Cicero, Kennedy und Obama nutzten Dreiergruppen, weil das menschliche Gehirn Rhythmen in Dreiergruppen als besonders einprägsam und abgeschlossen empfindet.',schritte:['Nimm eine Aussage, die du in einem Gespräch machen willst.','Forme sie in drei parallele, kurze Teile um (z. B. „Wir brauchen mehr Klarheit, mehr Mut, und vor allem mehr Konsequenz").','Sprich die drei Teile mit steigender Betonung – der dritte Teil trägt die stärkste Aussage.']},{id:'c3',titel:'Blickkontakt-Anker',hintergrund:'Ständig wandernder Blick wirkt unsicher; wer den Blickkontakt zu einer Person für 3–5 Sekunden hält, bevor er zur nächsten wechselt, wirkt präsenter und glaubwürdiger.',schritte:['Führe ein Gespräch (oder übe vor dem Spiegel/der Kamera) und wähle bewusst einen Satz pro Gedanke, den du einer Person direkt zuwendest.','Halte den Blickkontakt bis zum Ende des Gedankens, statt vorzeitig wegzuschauen.','Wechsle erst mit dem nächsten Gedanken bewusst den Fokus.']},{id:'c4',titel:'Die tiefe Stimme (Grounding)',hintergrund:'Eine tiefere, ruhigere Stimmlage wird unbewusst mit Kompetenz und Ruhe assoziiert; Nervosität treibt die Stimme dagegen automatisch nach oben.',schritte:['Stelle dich aufrecht hin, atme tief in den Bauch statt in die Brust.','Sprich einen Satz zunächst hastig und hoch, dann bewusst langsamer und mit gesenkter Stimme.','Achte auf den Unterschied in der Wirkung – nimm das langsamere, tiefere Sprechen als deinen Standard für wichtige Momente.']},{id:'c5',titel:'Storytelling statt Statistik',hintergrund:'Menschen erinnern sich an Geschichten deutlich besser als an Zahlen oder abstrakte Aussagen – Aristoteles nannte dies bereits das Prinzip des „Pathos" in der Rhetorik.',schritte:['Nimm eine trockene Tatsache oder Zahl, die du vermitteln willst.','Verpacke sie in eine kurze, konkrete Situation mit einer Person, einem Ort und einem Moment („Stell dir vor, ein Kunde steht um 22 Uhr vor verschlossener Tür...").','Vergleiche die Wirkung der reinen Zahl mit der Wirkung der Geschichte.']},{id:'c6',titel:'Power-Posture vor wichtigen Momenten',hintergrund:'Eine offene, aufrechte Körperhaltung vor einem wichtigen Gespräch kann das eigene Sicherheitsgefühl messbar beeinflussen, auch wenn niemand sonst anwesend ist.',schritte:['Stell dich zwei Minuten vor einem wichtigen Gespräch aufrecht hin, Schultern zurück, Kinn leicht angehoben.','Atme bewusst tief und langsam.','Betritt den Raum/das Gespräch direkt im Anschluss, ohne die Haltung sofort wieder zusammensacken zu lassen.']},{id:'c7',titel:'Aktiv zuhören und spiegeln',hintergrund:'Menschen empfinden ihr Gegenüber als charismatischer, wenn sie sich wirklich gehört fühlen – nicht wenn der Redner am meisten redet.',schritte:['Stelle im nächsten Gespräch bewusst eine Rückfrage zu dem, was die andere Person gerade gesagt hat, bevor du deinen eigenen Punkt einbringst.','Fasse ihre Kernaussage kurz in eigenen Worten zusammen ("Wenn ich dich richtig verstehe...").','Beobachte, wie sich die Gesprächsatmosphäre dadurch verändert.']},{id:'c8',titel:'Der starke Einstieg (Cold Open)',hintergrund:'Cicero empfahl, eine Rede nicht mit einer Entschuldigung oder einem trockenen Fakt zu beginnen, sondern mit einem Satz, der sofort Aufmerksamkeit bindet.',schritte:['Formuliere für deine nächste Präsentation oder Ansage einen Eröffnungssatz, der eine Frage, ein Bild oder eine überraschende Behauptung enthält.','Vermeide Einstiege wie „Also, ich wollte kurz..." – starte direkt mit der Substanz.','Teste beide Varianten laut und vergleiche die Wirkung.']},{id:'c9',titel:'Der \'Name-Drop\' im Gespräch',hintergrund:'Menschen reagieren nachweislich positiv darauf, ihren eigenen Namen im Gespräch zu hören — es erzeugt Aufmerksamkeit und ein Gefühl von persönlicher Ansprache.',schritte:['Merke dir zu Beginn eines Gesprächs bewusst den Namen deines Gegenübers.','Verwende ihn mindestens zweimal im Verlauf des Gesprächs, an natürlichen Stellen.','Beobachte, wie sich die Reaktion des Gegenübers dadurch verändert.']},{id:'c10',titel:'Spiegeln der Körpersprache',hintergrund:'Menschen empfinden Gegenüber als sympathischer, wenn diese sich unbewusst in Haltung und Tempo angleichen — ein Grundprinzip des Rapport-Aufbaus.',schritte:['Beobachte im nächsten Gespräch unauffällig die Körperhaltung deines Gegenübers.','Gleiche deine eigene Haltung (nicht das exakte Verhalten) leicht an — z. B. ähnliches Sprechtempo oder ähnliche Energie.','Achte darauf, ob sich die Gesprächsatmosphäre entspannter anfühlt.']},{id:'c11',titel:'Die \'Ja-Straße\'',hintergrund:'Wenn jemand mehrfach hintereinander \'Ja\' sagt, entsteht eine positive Gesprächsdynamik, die auch für die nächste, wichtigere Frage hilfreich ist.',schritte:['Formuliere zu Beginn eines wichtigen Gesprächs zwei bis drei Fragen, die dein Gegenüber mit hoher Wahrscheinlichkeit bejaht.','Stelle sie nacheinander, bevor du zur eigentlichen Kernfrage kommst.','Beobachte, wie sich die Gesprächsbereitschaft dadurch entwickelt.']},{id:'c12',titel:'Lächeln vor dem Sprechen',hintergrund:'Ein kurzes, echtes Lächeln vor dem ersten Satz verändert nachweislich den Tonfall der Stimme — Zuhörer nehmen das unbewusst als Wärme wahr, auch am Telefon.',schritte:['Lächle bewusst kurz, bevor du in einem wichtigen Gespräch oder Telefonat den ersten Satz sprichst.','Achte darauf, wie sich dein eigener Tonfall dadurch verändert.','Wiederhole das bei jedem neuen Gesprächseinstieg.']},{id:'c13',titel:'Der stille Abschluss',hintergrund:'Nach einem starken letzten Satz nichts mehr hinzuzufügen wirkt selbstbewusster, als die Aussage durch Nachsätze zu relativieren.',schritte:['Formuliere für dein nächstes wichtiges Gespräch einen klaren Schlusssatz.','Sprich ihn aus und schweige danach bewusst, statt ihn mit \'so ungefähr\' oder ähnlichem abzuschwächen.','Beobachte die Wirkung der Stille nach einer klaren Aussage.']},{id:'c14',titel:'Status durch Raumnutzung',hintergrund:'Wer sich im Raum bewusst und ruhig bewegt (statt zusammengekauert in einer Ecke zu stehen), wird von anderen unbewusst als selbstsicherer wahrgenommen.',schritte:['Achte in deiner nächsten Präsentation oder deinem nächsten Standgespräch bewusst darauf, Raum einzunehmen, statt dich klein zu machen.','Vermeide es, dich hinter Gegenständen (Tresen, Laptop) zu verstecken, wenn es die Situation erlaubt.','Beobachte, wie sich dein eigenes Sicherheitsgefühl dadurch verändert.']}];export const CHARISMA_CHALLENGES=[{id:'ch1',tag:'Stimme',titel:'Die bewusste Pause',aufgabe:'Führe heute mindestens ein Gespräch, in dem du nach einer wichtigen Aussage bewusst 2–3 Sekunden schweigst, statt die Stille mit \'äh\' oder Zusätzen zu füllen.',dauer:'5 Minuten'},{id:'ch2',tag:'Körpersprache',titel:'Blickkontakt halten',aufgabe:'Halte in deinem nächsten Gespräch bei jedem wichtigen Gedanken den Blickkontakt bis zum Satzende, bevor du wegschaust.',dauer:'Ganztägig'},{id:'ch3',tag:'Wortwahl',titel:'Ein Füllwort eliminieren',aufgabe:'Wähle ein Füllwort (z. B. \'irgendwie\' oder \'eigentlich\') und achte einen ganzen Tag bewusst darauf, es zu vermeiden.',dauer:'Ganztägig'},{id:'ch4',tag:'Storytelling',titel:'Zahl in Geschichte verwandeln',aufgabe:'Verpacke heute eine trockene Information oder Zahl in eine kurze, konkrete Geschichte mit Person, Ort und Moment.',dauer:'10 Minuten'},{id:'ch5',tag:'Mut',titel:'Position offen vertreten',aufgabe:'Vertritt in einem Gespräch heute eine Meinung klar und direkt, statt sie vorsichtig zu relativieren (\'ich glaube\', \'vielleicht\').',dauer:'Ganztägig'},{id:'ch6',tag:'Stilmittel',titel:'Tricolon einbauen',aufgabe:'Formuliere heute mindestens einen Satz als Dreiergruppe (Tricolon), z. B. \'Klarheit, Konsequenz, Ergebnis\'.',dauer:'10 Minuten'},{id:'ch7',tag:'Zuhören',titel:'Aktiv paraphrasieren',aufgabe:'Fasse in einem Gespräch die Aussage deines Gegenübers einmal bewusst in eigenen Worten zusammen, bevor du antwortest.',dauer:'Ganztägig'},{id:'ch8',tag:'Körpersprache',titel:'Aufrechte Haltung',aufgabe:'Stell dich vor einem wichtigen Gespräch zwei Minuten lang bewusst aufrecht hin, Schultern zurück, und atme tief durch.',dauer:'2 Minuten'},{id:'ch9',tag:'Wortwahl',titel:'Ein Wort aufwerten',aufgabe:'Ersetze heute bewusst ein einfaches Wort (z. B. \'gut\', \'viel\', \'wichtig\') durch eine gehobenere Alternative aus der Schatzkiste.',dauer:'5 Minuten'},{id:'ch10',tag:'Latein',titel:'Ein Zitat einbauen',aufgabe:'Baue heute ein passendes lateinisches Zitat aus dem Latein-Trainer in ein Gespräch oder eine Nachricht ein — inklusive kurzer Erklärung.',dauer:'10 Minuten'},{id:'ch11',tag:'Einwand',titel:'Einwand vorwegnehmen',aufgabe:'Antizipiere in einer Diskussion einen möglichen Einwand, bevor er kommt, und entkräfte ihn proaktiv.',dauer:'Ganztägig'},{id:'ch12',tag:'Stimme',titel:'Langsamer sprechen',aufgabe:'Sprich heute in einem wichtigen Gespräch bewusst 20 % langsamer, als es sich zunächst richtig anfühlt.',dauer:'Ganztägig'},{id:'ch13',tag:'Storytelling',titel:'Starker Einstieg',aufgabe:'Beginne deine nächste Präsentation, E-Mail oder Ansage mit einer Frage oder einem Bild statt mit einer Floskel.',dauer:'10 Minuten'},{id:'ch14',tag:'Mut',titel:'Nein sagen',aufgabe:'Lehne heute eine Bitte oder Anfrage klar und ohne übermäßige Rechtfertigung ab, wenn es angebracht ist.',dauer:'Ganztägig'},{id:'ch15',tag:'Stilmittel',titel:'Antithese formulieren',aufgabe:'Formuliere einen Gedanken heute als Gegensatzpaar, z. B. \'Nicht mehr Aufwand, sondern klarere Prioritäten\'.',dauer:'10 Minuten'},{id:'ch16',tag:'Zuhören',titel:'Eine Frage mehr stellen',aufgabe:'Stelle in deinem nächsten Gespräch eine zusätzliche Rückfrage, bevor du deinen eigenen Standpunkt einbringst.',dauer:'Ganztägig'},{id:'ch17',tag:'Körpersprache',titel:'Gestik bewusst einsetzen',aufgabe:'Nutze in einem Gespräch bewusst offene Handgesten, um deine Aussagen zu unterstreichen, statt die Arme zu verschränken.',dauer:'Ganztägig'},{id:'ch18',tag:'Wortwahl',titel:'Konkrete Zahl statt \'viele\'',aufgabe:'Ersetze heute mindestens einmal eine vage Mengenangabe (\'viele\', \'oft\') durch eine konkrete Zahl oder ein konkretes Beispiel.',dauer:'5 Minuten'},{id:'ch19',tag:'Überzeugen',titel:'Gemeinsamkeit zuerst',aufgabe:'Beginne eine schwierige Diskussion heute damit, einen Punkt zu benennen, in dem ihr euch einig seid, bevor du die Differenz ansprichst.',dauer:'Ganztägig'},{id:'ch20',tag:'Stimme',titel:'Tiefer sprechen',aufgabe:'Achte in einem wichtigen Gespräch bewusst darauf, aus dem Bauch statt aus der Brust zu atmen und dadurch tiefer zu sprechen.',dauer:'5 Minuten'},{id:'ch21',tag:'Stilmittel',titel:'Rhetorische Frage nutzen',aufgabe:'Baue heute eine rhetorische Frage in ein Gespräch oder eine Präsentation ein, um einen Punkt zu unterstreichen.',dauer:'10 Minuten'},{id:'ch22',tag:'Mut',titel:'Unbequeme Wahrheit ansprechen',aufgabe:'Sprich heute einen Punkt an, den du sonst eher vermeidest — sachlich, klar und ohne Umschweife.',dauer:'Ganztägig'},{id:'ch23',tag:'Charisma',titel:'Namen bewusst nutzen',aufgabe:'Sprich dein Gegenüber in einem Gespräch heute mindestens zweimal bewusst mit Namen an.',dauer:'Ganztägig'},{id:'ch24',tag:'Überzeugen',titel:'Perspektivwechsel anbieten',aufgabe:'Formuliere in einer Diskussion heute den Satz: \'Stellen wir uns das aus Sicht von... vor\', um eine neue Perspektive zu öffnen.',dauer:'10 Minuten'},{id:'ch25',tag:'Stimme',titel:'Betonung variieren',aufgabe:'Lies dir einen wichtigen Satz für heute laut vor und probiere drei verschiedene Betonungen, bevor du ihn im Gespräch nutzt.',dauer:'5 Minuten'},{id:'ch26',tag:'Reflexion',titel:'Gespräch nachbereiten',aufgabe:'Notiere dir nach einem wichtigen Gespräch heute in zwei Sätzen, was rhetorisch gut lief und was du nächstes Mal anders machen willst.',dauer:'5 Minuten'},{id:'ch27',tag:'Stilmittel',titel:'Anapher testen',aufgabe:'Wiederhole in einem Satz heute bewusst den Satzanfang, z. B. \'Wir wollen Klarheit, wir wollen Tempo, wir wollen Ergebnisse\'.',dauer:'10 Minuten'},{id:'ch28',tag:'Charisma',titel:'Pause vor der Antwort',aufgabe:'Lass dir in einem Gespräch heute bewusst eine kurze Pause, bevor du auf eine Frage antwortest, statt sofort zu reagieren.',dauer:'Ganztägig'},{id:'ch29',tag:'Überzeugen',titel:'Story statt Statistik',aufgabe:'Erzähle heute in einem beruflichen Kontext eine kurze Geschichte, statt nur Zahlen oder Fakten zu präsentieren.',dauer:'10 Minuten'},{id:'ch30',tag:'Wortwahl',titel:'Füllwort-freier Tag',aufgabe:'Versuche heute einen ganzen Tag lang komplett ohne \'äh\', \'ähm\' oder \'halt\' auszukommen — Stille statt Lückenfüller.',dauer:'Ganztägig'}];export const SITUATIVE_SKRIPTE=[{id:'sk1',situation:'Preisverhandlung bei einer Catering-Anfrage',kontext:'Ein Kunde findet dein Angebot \'zu teuer\' und fragt nach Rabatt.',skript:['Kunde: „Das ist uns ehrlich gesagt zu teuer, geht da noch was?"','Du: „Ich verstehe, dass der Preis erstmal ein wichtiger Faktor ist. Lassen Sie uns kurz schauen, was genau im Preis enthalten ist — vielleicht lässt sich am Umfang etwas anpassen, ohne an der Qualität zu sparen."','Kunde: „Was würde das konkret bedeuten?"','Du: „Wir könnten zum Beispiel die Anzahl der Gänge reduzieren oder ein etwas einfacheres Menü wählen — dafür bleibt die Qualität und der Service exakt gleich. Was ist Ihnen wichtiger: der volle Umfang oder ein angepasstes Budget?"'],tipp:'Nicht sofort den Preis senken — stattdessen den Wert erklären und dem Kunden die Wahl zwischen Umfang und Preis geben. Das wirkt souverän statt nachgiebig.'},{id:'sk2',situation:'Reklamation am Stand: \'Das Essen war kalt\'',kontext:'Ein Gast beschwert sich lautstark vor anderen Kunden.',skript:['Gast: „Das Essen war kalt, das ist doch eine Frechheit!"','Du: „Das tut mir leid, das darf natürlich nicht passieren — darf ich Ihnen sofort ein frisches Gericht machen?"','Gast: „Na gut, aber das nächste Mal achte ich da drauf."','Du: „Das verstehe ich völlig. Ich gebe Ihnen dieses Mal noch ein Getränk dazu, damit der Abend trotzdem in guter Erinnerung bleibt."'],tipp:'Erst Verantwortung übernehmen, dann konkrete Lösung anbieten — vor Publikum ruhig und lösungsorientiert bleiben, statt zu rechtfertigen oder zurückzuweisen.'},{id:'sk3',situation:'Ein zu forscher Kunde am Stand',kontext:'Ein Kunde drängelt, unterbricht andere und wird ungeduldig.',skript:['Kunde: „Wie lange dauert das denn noch, ich steh hier schon ewig!"','Du: „Ich verstehe die Ungeduld — in circa zwei Minuten sind Sie dran, ich sorge dafür, dass es zügig weitergeht."','Kunde: „Na hoffentlich."','Du: (ruhig, mit einem Lächeln) „Ich mache das gerade extra sorgfältig, damit es bei Ihnen genauso gut schmeckt wie bei den anderen."'],tipp:'Ruhe und ein leichter, freundlicher Humor entschärfen Ungeduld besser als Rechtfertigung oder Eile, die Fehler produziert.'},{id:'sk4',situation:'Networking: Sich in 30 Sekunden vorstellen',kontext:'Du triffst auf einer Messe oder einem Event eine potenziell wichtige Kontaktperson.',skript:['Du: „Ich bin Felix, ich betreibe ein Asiatisches Food-Truck- und Catering-Unternehmen — wir sorgen dafür, dass Events nicht nur gut aussehen, sondern auch richtig gut schmecken."','Gegenüber: „Interessant, für welche Art von Events macht ihr das?"','Du: „Von kleinen Firmenfeiern bis zu größeren Hochzeiten — was uns auszeichnet, ist, dass wir Streetfood-Qualität mit dem Anspruch eines echten Caterings verbinden."'],tipp:'Ein prägnanter, bildhafter erster Satz (nicht nur \'Ich mache Catering\') bleibt hängen und öffnet die Tür für die nächste Frage.'},{id:'sk5',situation:'Ein Angebot höflich, aber bestimmt ablehnen',kontext:'Ein Geschäftspartner oder Lieferant macht einen Vorschlag, der für dich nicht passt.',skript:['Partner: „Wie wäre es, wenn wir das so machen?"','Du: „Danke für den Vorschlag — für uns passt das aktuell aus [konkretem Grund] nicht. Was für uns funktionieren würde, ist [Alternative]."'],tipp:'Erst wertschätzen, dann klar und ohne lange Rechtfertigung ablehnen, direkt mit einer Alternative — das wirkt souverän statt konfliktscheu.'},{id:'sk6',situation:'Schwieriges Feedback an eine Mitarbeiterin/einen Mitarbeiter',kontext:'Ein wiederkehrender Fehler muss angesprochen werden, ohne die Beziehung zu belasten.',skript:['Du: „Mir ist aufgefallen, dass [konkrete Beobachtung] in den letzten Tagen öfter vorkam. Wie siehst du das selbst?"','Mitarbeiter: „Stimmt, das war mir noch nicht so bewusst."','Du: „Gut, dass wir das ansprechen. Was bräuchtest du, damit das nächste Mal einfacher klappt?"'],tipp:'Mit einer konkreten Beobachtung statt einer pauschalen Kritik beginnen und die Person aktiv nach ihrer Sicht und Lösung fragen — das wirkt kooperativ statt anklagend.'},{id:'sk7',situation:'Krisenkommunikation nach einem Fehler',kontext:'Ein Fehler ist bereits passiert (z. B. eine falsche Lieferung) und muss kommuniziert werden.',skript:['Du: „Uns ist bei Ihrer Bestellung ein Fehler unterlaufen — das möchte ich Ihnen ehrlich und direkt sagen, statt es zu beschönigen."','Kunde: „Was ist denn passiert?"','Du: „[Konkrete, kurze Erklärung ohne Ausreden]. Wir korrigieren das jetzt so: [konkrete Lösung]."'],tipp:'Fehler offen benennen, bevor der Kunde ihn selbst entdeckt — das schafft mehr Vertrauen als jede Ausrede, und eine konkrete Lösung beruhigt schneller als eine Entschuldigung allein.'},{id:'sk8',situation:'Cross-Selling am Stand ohne aufdringlich zu wirken',kontext:'Ein Kunde hat bereits bestellt — du möchtest ein Zusatzprodukt anbieten.',skript:['Du: „Dazu passt übrigens unser [Zusatzprodukt] besonders gut — viele nehmen das gerne mit dazu."','Kunde: „Ach, was ist das denn?"','Du: „[Kurze, appetitliche Beschreibung in einem Satz]."'],tipp:'Als beiläufige Empfehlung formulieren (\'viele nehmen das dazu\'), nicht als Verkaufsdruck — soziale Bewährtheit wirkt einladender als eine direkte Verkaufsfrage.'},{id:'sk9',situation:'Ein zögernder Kunde am Stand',kontext:'Ein Kunde steht unentschlossen vor der Karte und blockiert die Schlange.',skript:['Du: „Darf ich Ihnen kurz meine zwei Favoriten empfehlen? Dann geht die Entscheidung schneller."','Kunde: „Gerne, ich kann mich nicht entscheiden."','Du: „Wenn Sie es eher würzig mögen, nehmen Sie [Gericht A] — wenn eher mild, [Gericht B]. Beides kommt sehr gut an."'],tipp:'Eine Auswahl auf zwei klare Optionen reduzieren, statt die ganze Karte zu erklären — das beschleunigt die Entscheidung und wirkt kompetent statt aufdringlich.'},{id:'sk10',situation:'Ein Stammkunde erwartet eine Ausnahme',kontext:'Ein bekannter Kunde bittet um eine Sonderregel, die du eigentlich nicht machst.',skript:['Kunde: „Ich bin doch Stammkunde, da könnt ihr mir sicher eine Ausnahme machen, oder?"','Du: „Ich schätze es sehr, dass Sie so oft bei uns sind — genau deshalb möchte ich fair bleiben und für alle die gleichen Regeln halten."','Kunde: „Na gut, verstehe ich."','Du: „Was ich Ihnen anbieten kann, ist [alternative Geste, z. B. ein kleines Extra] — als Dankeschön für Ihre Treue."'],tipp:'Wertschätzung ausdrücken, ohne die eigene Linie aufzugeben — und stattdessen eine andere, planbare Geste anbieten.'},{id:'sk11',situation:'Verhandlung mit einem Lieferanten',kontext:'Ein Lieferant will die Preise erhöhen, du willst das nicht kampflos hinnehmen.',skript:['Lieferant: „Wir müssen die Preise um 8 % anheben."','Du: „Ich verstehe, dass die Kosten gestiegen sind. Bei einer Erhöhung dieser Größenordnung würde ich aber gerne über die Menge oder die Lieferkonditionen sprechen, damit sich das für uns beide trägt."','Lieferant: „Was schwebt Ihnen vor?"','Du: „Wie wäre es, wenn wir bei 4 % bleiben, dafür aber die Bestellmenge erhöhen?"'],tipp:'Nicht direkt ablehnen oder sofort zustimmen — stattdessen einen Gegenvorschlag mit klarem Vorteil für beide Seiten anbieten.'},{id:'sk12',situation:'Small Talk in eine Geschäftschance verwandeln',kontext:'Ein lockeres Gespräch bei einem Event, das du für dein Geschäft nutzen möchtest.',skript:['Gegenüber: „Und, was machst du beruflich?"','Du: „Ich betreibe ein Food-Truck- und Catering-Unternehmen — wir sorgen dafür, dass Events kulinarisch in Erinnerung bleiben. Und bei dir, worum geht\'s beruflich?"','Gegenüber: „Wir organisieren tatsächlich öfter Firmenevents."','Du: „Das klingt spannend — magst du mir kurz erzählen, wie so ein Event bei euch typischerweise abläuft?"'],tipp:'Die eigene Vorstellung kurz halten, dann sofort eine Rückfrage stellen — echtes Interesse öffnet mehr Türen als ein langer Pitch.'},{id:'sk13',situation:'Eine Deadline-Anfrage clever timen',kontext:'Ein Kunde will eine Zusage sofort, du brauchst aber noch Bedenkzeit.',skript:['Kunde: „Können Sie mir das jetzt gleich zusagen?"','Du: „Ich möchte Ihnen ungern etwas versprechen, das ich nicht halten kann — geben Sie mir bis morgen früh, dann melde ich mich mit einer verbindlichen Antwort."'],tipp:'Verbindlichkeit signalisieren (konkreter Zeitpunkt), statt vage zu vertrösten — das wirkt zuverlässiger als eine überstürzte Zusage.'},{id:'sk14',situation:'Kritik von einem Kunden auf Social Media beantworten',kontext:'Ein negativer Kommentar unter einem Post, öffentlich sichtbar.',skript:['Kommentar: „Bin echt enttäuscht, das Essen war letztes Mal nicht gut."','Du (öffentliche Antwort): „Das tut uns leid zu hören — das entspricht nicht unserem Anspruch. Magst du uns per Nachricht schreiben, wann das war? Wir möchten das wiedergutmachen."'],tipp:'Öffentlich kurz, ruhig und lösungsorientiert antworten, Details dann ins Private verlagern — schützt sowohl den Ruf als auch das Gespräch vor eskalierender Öffentlichkeit.'}];export const CICERO_REDETEILE=[{id:'ct1',nr:1,name:'Exordium',uebersetzung:'Einleitung',funktion:'Gewinnt die Aufmerksamkeit und das Wohlwollen des Publikums, bevor der eigentliche Inhalt beginnt. Cicero empfahl, hier niemals mit einer Entschuldigung oder trockenen Fakten zu starten.',beispiel:'„Stellen Sie sich vor, Sie hätten heute nur eine einzige Entscheidung zu treffen..." statt „Ich wollte kurz etwas zu unserem Budget sagen."'},{id:'ct2',nr:2,name:'Narratio',uebersetzung:'Sachverhaltsdarstellung',funktion:'Schildert den relevanten Sachverhalt klar, chronologisch und ohne Umschweife — die Grundlage, auf der später argumentiert wird.',beispiel:'„Vor drei Monaten haben wir X eingeführt. Seitdem zeigt sich Y."'},{id:'ct3',nr:3,name:'Argumentatio (Confirmatio)',uebersetzung:'Beweisführung',funktion:'Der Kern der Rede: Hier werden die eigenen Argumente systematisch aufgebaut und belegt — mit Fakten, Beispielen und logischer Schlüssigkeit.',beispiel:'„Drei Gründe sprechen dafür: Erstens..., zweitens..., drittens..."'},{id:'ct4',nr:4,name:'Refutatio',uebersetzung:'Widerlegung der Gegenargumente',funktion:'Nimmt mögliche Einwände vorweg und entkräftet sie aktiv, statt sie dem Publikum zu überlassen — signalisiert Souveränität und Redlichkeit.',beispiel:'„Man könnte einwenden, dass X — doch genau das übersieht, dass..."'},{id:'ct5',nr:5,name:'Peroratio',uebersetzung:'Schluss',funktion:'Fasst die Kernbotschaft pointiert zusammen und appelliert emotional an das Publikum, um die Rede wirkungsvoll und einprägsam zu beenden.',beispiel:'„Am Ende bleibt eine einzige Frage: Wollen wir bei X bleiben, oder wollen wir Y wagen?"'}];export const GENERATOR_VORLAGEN=[{id:'g1',ziel:'ueberzeugen',vorlage:'Im Kern lässt sich das auf einen Punkt zurückführen: {situation}.'},{id:'g2',ziel:'ueberzeugen',vorlage:'Stellen wir uns kurz vor, was passiert, wenn wir bei {situation} nichts ändern.'},{id:'g3',ziel:'ueberzeugen',vorlage:'Drei Gründe sprechen für {situation}: Erstens..., zweitens..., drittens...'},{id:'g4',ziel:'deeskalieren',vorlage:'Ich verstehe, dass {situation} gerade für Frust sorgt — lassen Sie uns gemeinsam schauen, wie wir das lösen.'},{id:'g5',ziel:'deeskalieren',vorlage:'Das tut mir leid wegen {situation}. Darf ich Ihnen direkt eine Lösung anbieten?'},{id:'g6',ziel:'deeskalieren',vorlage:'Bei allem Verständnis für {situation} — lassen Sie uns das sachlich in Ruhe klären.'},{id:'g7',ziel:'verkaufen',vorlage:'Dazu passt übrigens {situation} besonders gut — das nehmen viele gerne mit.'},{id:'g8',ziel:'verkaufen',vorlage:'Wenn Sie {situation} mögen, dann lohnt sich auch ein Blick auf...'},{id:'g9',ziel:'verkaufen',vorlage:'Viele unserer Gäste kombinieren {situation} gerne mit...'},{id:'g10',ziel:'ablehnen',vorlage:'Danke für den Vorschlag zu {situation} — für uns passt das aktuell nicht, weil...'},{id:'g11',ziel:'ablehnen',vorlage:'Ich habe {situation} mir genau angesehen, muss aber ehrlich absagen. Was für uns funktionieren würde, ist...'},{id:'g12',ziel:'vorstellen',vorlage:'Ich bin Felix, und mein Fokus liegt auf {situation} — das bedeutet konkret, dass...'},{id:'g13',ziel:'vorstellen',vorlage:'Worüber ich mich am meisten freue, ist {situation} — darf ich kurz erzählen, warum?'},{id:'g14',ziel:'vorstellen',vorlage:'Kurz zu mir: {situation}. Und womit beschäftigen Sie sich gerade?'}];export const GENERATOR_ZIELE=[{id:'ueberzeugen',label:'Überzeugen'},{id:'deeskalieren',label:'Deeskalieren'},{id:'verkaufen',label:'Verkaufen'},{id:'ablehnen',label:'Ablehnen'},{id:'vorstellen',label:'Vorstellen'}];export const SOKRATISCHE_SCHRITTE=[{titel:'1. Naiv fragen',beschreibung:'Stelle eine offene, scheinbar einfache Frage nach der Definition ("Was ist eigentlich Gerechtigkeit/Mut/Erfolg für dich?"). Ziel ist, die Grundlage der Position des Gegenübers offenzulegen.',beispiel:'A: „Erfolg bedeutet für mich, viel Geld zu verdienen." B: „Interessant — was genau meinst du mit \'viel\'? Und reicht Geld allein schon für Erfolg, oder gehört noch etwas dazu?"'},{titel:'2. Zustimmung einholen',beschreibung:'Lass dir die Definition oder Behauptung in eigenen Worten bestätigen, damit später kein Ausweichen möglich ist ("Verstehe ich dich richtig, dass...?").',beispiel:'B: „Verstehe ich dich also richtig: Wer viel Geld hat, ist für dich automatisch erfolgreich — unabhängig davon, wie er es bekommen hat oder wie es ihm dabei geht?" A: „Ja, genau."'},{titel:'3. Konsequenzen ableiten',beschreibung:'Leite gemeinsam logische Folgerungen aus der Definition ab, am besten anhand eines konkreten Beispiels oder Grenzfalls.',beispiel:'B: „Dann wäre also auch ein Lottogewinner oder ein Betrüger mit viel Geld automatisch \'erfolgreich\' in deinem Sinne, unabhängig vom Weg dorthin?"'},{titel:'4. Widerspruch aufzeigen',beschreibung:'Zeige, wo diese Folgerung der ursprünglichen Behauptung widerspricht oder mit anderen Überzeugungen des Gegenübers kollidiert.',beispiel:'A: „Nein, so meinte ich das eigentlich nicht — ein Betrüger ist für mich nicht wirklich erfolgreich." B: „Dann scheint \'Geld allein\' also doch nicht deine eigentliche Definition zu sein."'},{titel:'5. Gemeinsam weiterdenken',beschreibung:'Statt zu triumphieren, ladet ihr gemeinsam ein, die Definition zu verfeinern. Ziel ist geteilte Erkenntnis, nicht ein „Sieg".',beispiel:'B: „Vielleicht gehört also auch dazu, wie man zu etwas gekommen ist, nicht nur wie viel es ist. Wie würdest du \'Erfolg\' jetzt neu fassen?"'}];export const SCHOPENHAUER_KUNSTGRIFFE=[{nr:1,titel:'Erweiterung',beschreibung:'Die gegnerische Aussage über ihre eigentlichen Grenzen hinaus verallgemeinern, um sie leichter angreifbar zu machen.',beispiel:'A: „Wir sollten mehr in erneuerbare Energien investieren." B: „Ach, du willst also, dass wir sofort alle Kohlekraftwerke abschalten und das Land im Dunkeln sitzt?"',beispiel2:'A: „Wir sollten in unserer Beziehung öfter über Geld reden." B: „Ach, du willst also, dass wir nur noch über Finanzen sprechen und nie mehr romantisch sind?"'},{nr:2,titel:'Homonymie ausnutzen',beschreibung:'Ein Wort in einer anderen Bedeutung verwenden, als es der Gegner ursprünglich meinte.',beispiel:'A: „Jeder Mensch hat ein Recht auf Freiheit." B: „Wenn dir Freiheit so wichtig ist, warum forderst du dann Steuererhöhungen, die die wirtschaftliche Freiheit der Bürger einschränken?"',beispiel2:'A: „Ich will einfach nur ehrlich sein." B: „Wenn dir Ehrlichkeit so wichtig ist, warum verschweigst du dann deine wahren Gefühle aus „Höflichkeit"?"'},{nr:3,titel:'Unzulässige Verallgemeinerung',beschreibung:'Eine Aussage, die nur für einen speziellen Fall galt, so behandeln, als gelte sie uneingeschränkt.',beispiel:'A: „In meiner Abteilung hat Homeoffice gut funktioniert." B: „Du sagst also, Homeoffice funktioniert grundsätzlich für jeden Job?"',beispiel2:'A: „Dieser eine Kollege hat mich enttäuscht." B: „Also sagst du, man kann sich grundsätzlich auf niemanden im Team verlassen?"'},{nr:4,titel:'Absicht verschleiern',beschreibung:'Die eigenen Zwischenschritte verbergen, damit der Gegner nicht widerspricht, bevor die Schlussfolgerung „zuschnappt".',beispiel:'B stellt nacheinander harmlos wirkende Fragen („Sicherheit ist doch wichtig, oder?" … „Und der Staat soll dafür sorgen, oder?"), bis A am Ende scheinbar zwangsläufig mehr Überwachung zustimmen muss.',beispiel2:'In einem Verkaufsgespräch werden erst mehrere harmlose Ja-Fragen gestellt, bevor unauffällig der eigentliche Vertragsabschluss folgt.'},{nr:5,titel:'Falsche Prämissen einschleusen',beschreibung:'Unbewiesene Behauptungen still als Voraussetzung in die Argumentation einbauen.',beispiel:'B: „Da wir uns ja einig sind, dass der Staat ohnehin zu viel eingreift, folgt daraus, dass diese Regel abgeschafft gehört." (Diese „Einigkeit" gab es nie.)',beispiel2:'B: „Da wir uns ja einig sind, dass Qualität wichtiger ist als der Preis, sollten wir natürlich das teurere Angebot nehmen." (Diese Einigkeit gab es nie.)'},{nr:6,titel:'Petitio principii',beschreibung:'Die eigentlich noch zu beweisende Aussage bereits stillschweigend als Prämisse voraussetzen.',beispiel:'B: „Diese Diät ist gesund, weil sie dem Körper eben guttut." (Dass sie guttut, ist genau das, was erst noch zu beweisen wäre.)',beispiel2:'B: „Diese Führungskraft ist kompetent, weil sie eben echte Führungsqualitäten mitbringt." (Genau das wäre erst noch zu belegen.)'},{nr:7,titel:'Fragen kumulieren',beschreibung:'Viele Einzelfragen stellen, deren Antworten am Ende die gewünschte Schlussfolgerung „logisch" erzwungen erscheinen lassen.',beispiel:'B: „Findest du Sicherheit wichtig? Soll der Staat für Sicherheit sorgen? Dann stimmst du also mehr Überwachungskameras zu."',beispiel2:'B: „Ist dir Gesundheit wichtig? Gehört Bewegung nicht dazu? Dann solltest du doch mit mir ins Fitnessstudio kommen."'},{nr:8,titel:'Den Gegner reizen',beschreibung:'Ihn durch Provokation aus der Ruhe bringen, damit er unüberlegter und schwächer argumentiert.',beispiel:'B: „Das ist doch eine ziemlich naive Sichtweise, ehrlich gesagt." — A reagiert gereizt und formuliert das nächste Argument unpräziser.',beispiel2:'B: „Das klingt ja wieder typisch für dich, immer so übervorsichtig zu sein." — A reagiert gereizt und argumentiert in der Folge unpräziser.'},{nr:9,titel:'Reihenfolge durchkreuzen',beschreibung:'Fragen bewusst in anderer Reihenfolge stellen, um die geplante Argumentationslinie des Gegners zu stören.',beispiel:'A hat drei Fragen vorbereitet, die logisch aufeinander aufbauen sollen. B beantwortet gezielt zuerst Frage drei, dann eins, sodass A den roten Faden verliert.',beispiel2:'In einem Meeting werden die vorbereiteten Tagesordnungspunkte bewusst in anderer Reihenfolge behandelt, um die Argumentationslinie des Kollegen zu stören.'},{nr:10,titel:'Widersprüche ausschlachten',beschreibung:'Je nach Situation die Gegenposition wählen, um den Gegner in scheinbare Widersprüche zu seinen früheren Aussagen zu verwickeln.',beispiel:'B: „Letzte Woche hast du gesagt, der Staat solle sparen. Jetzt forderst du mehr Ausgaben für Bildung. Widersprichst du dir nicht selbst?"',beispiel2:'B: „Letztes Jahr wolltest du unbedingt umziehen, jetzt sagst du, du liebst diese Wohnung? Widersprichst du dir nicht?"'},{nr:11,titel:'Einzelfall zur Regel erklären',beschreibung:'Stimmt der Gegner einem Einzelfall zu, dies so behandeln, als hätte er der ganzen Regel zugestimmt.',beispiel:'A gibt zu: „Ja, dieser eine Fall von Missbrauch war real." B: „Damit gibst du also zu, dass das System grundsätzlich missbraucht wird."',beispiel2:'A gibt zu: „Ich war letzte Woche einmal zu spät." B: „Damit gibst du also zu, dass du grundsätzlich unzuverlässig bist."'},{nr:12,titel:'Vorteilhafte Begriffe wählen',beschreibung:'Wörter mit positiver oder negativer Färbung nutzen, um eine Sache emotional in die gewünschte Richtung zu lenken.',beispiel:'B nennt eine Gesetzesänderung „notwendige Reform", während er dieselbe Maßnahme beim Gegner als „Abbau von Arbeitnehmerrechten" bezeichnen würde.',beispiel2:'Eine Gehaltskürzung wird als „Anpassung an die Marktlage" bezeichnet, während dieselbe Maßnahme beim Wettbewerber „unfairer Lohnabbau" genannt würde.'},{nr:13,titel:'Scheinbare Wahlfreiheit',beschreibung:'Dem Gegner zwei Optionen anbieten, die beide der eigenen These nützen, als gäbe es keine dritte Möglichkeit.',beispiel:'B: „Bist du für Ordnung oder für Chaos?" — als gäbe es zwischen strikter Regulierung und völliger Regellosigkeit nichts dazwischen.',beispiel2:'B: „Willst du dich jetzt endlich entscheiden oder bleibst du für immer allein?" — als gäbe es zwischen beidem keine weiteren Möglichkeiten.'},{nr:14,titel:'Sieg einfach behaupten',beschreibung:'Eine unbewiesene Schlussfolgerung selbstbewusst so präsentieren, als sei sie längst erwiesen.',beispiel:'B: „Damit ist ja wohl eindeutig bewiesen, dass mein Standpunkt richtig ist." (Bewiesen wurde in Wahrheit nichts.)',beispiel2:'B: „Damit ist ja wohl klar, dass ich die ganze Zeit recht hatte." (Bewiesen wurde dabei nichts.)'},{nr:15,titel:'Falsche Analogie unterschieben',beschreibung:'Eine scheinbar ähnliche, aber tatsächlich unpassende Vergleichssituation vorschlagen, um die eigene Position zu stützen.',beispiel:'B: „Ein Staat ist wie eine Familie — eine Familie würde ja auch nie mehr ausgeben, als sie einnimmt." (Staatliche und private Haushalte funktionieren jedoch nach ganz anderen Regeln.)',beispiel2:'B: „Eine Beziehung ist wie ein Geschäft — man investiert und erwartet eine Rendite." (Ein unpassender Vergleich für zwischenmenschliche Nähe.)'},{nr:16,titel:'Argumentum ad hominem',beschreibung:'Die Person angreifen statt sich mit ihrem Argument inhaltlich auseinanderzusetzen.',beispiel:'B: „Was verstehst du schon davon — du hast ja nicht mal Wirtschaft studiert." (Das Argument selbst bleibt unangetastet.)',beispiel2:'B: „Du hast doch selbst schon mal einen ähnlichen Fehler gemacht, dein Einwand zählt also nicht."'},{nr:17,titel:'Spitzfindige Unterscheidung erfinden',beschreibung:'Wenn ein Argument trifft, eine künstliche Unterscheidung einführen, um sich der Konsequenz zu entziehen.',beispiel:'B: „Das war keine Lüge, das war lediglich eine \'ungenaue Darstellung der Sachlage\'."',beispiel2:'B: „Ich habe nicht gelogen, ich habe nur „ein paar Details ausgelassen"."'},{nr:18,titel:'Thema wechseln',beschreibung:'Merkt man, dass man zu verlieren droht, das Gespräch abrupt auf ein anderes Thema lenken.',beispiel:'B, sichtlich in der Defensive: „Aber was ist eigentlich mit dem viel größeren Problem des Klimawandels?"',beispiel2:'Im Streit über Unpünktlichkeit lenkt B plötzlich ab: „Aber du hast letzte Woche doch auch etwas vergessen!"'},{nr:19,titel:'Ins Allgemeine flüchten',beschreibung:'Einer konkreten, unangenehmen Frage ausweichen, indem man ins Vage und Allgemeine abgleitet.',beispiel:'A: „Wie genau willst du das konkret finanzieren?" B: „Naja, das Leben ist eben kompliziert, man muss das im großen Zusammenhang sehen."',beispiel2:'A: „Warum genau hast du das nicht erledigt?" B: „Naja, im Leben läuft eben nicht immer alles nach Plan."'},{nr:20,titel:'Voreilig triumphieren',beschreibung:'Auch wenn Prämissen nur teilweise zugestanden wurden, den vollen gewünschten Schluss siegessicher behaupten.',beispiel:'A: „Es mag vereinzelt Ausnahmen geben." B: „Aha! Du gibst also zu, dass meine gesamte These stimmt!"',beispiel2:'A: „Es mag vereinzelt Ausnahmen geben." B: „Aha, damit gibst du also zu, dass ich grundsätzlich recht habe!"'},{nr:21,titel:'Übertreiben, um lächerlich zu machen',beschreibung:'Ein schwaches Gegenargument nicht inhaltlich widerlegen, sondern durch Übertreibung ins Absurde ziehen.',beispiel:'A: „Vielleicht Tempo 30 in Wohngebieten." B: „Ach, dann fahren wir wohl bald alle nur noch mit dem Fahrrad, und die ganze Wirtschaft bricht zusammen!"',beispiel2:'B: „Wenn wir jetzt anfangen zu sparen, leben wir bald wie Bettler auf der Straße."'},{nr:22,titel:'Waffen umkehren',beschreibung:'Ein Argument, das der Gegner selbst vorgebracht hat, gegen ihn wenden.',beispiel:'A: „Wir sollten der Wissenschaft vertrauen." B: „Genau — und die Wissenschaft bestätigt in Wahrheit meinen Standpunkt, nicht deinen."',beispiel2:'A: „Wir sollten ehrlich zueinander sein." B: „Genau, deshalb sage ich dir jetzt ganz ehrlich, dass du hier maßlos übertreibst."'},{nr:23,titel:'Gereiztheit als Treffer deuten',beschreibung:'Reagiert der Gegner emotional, dies als Zeichen werten, einen wunden Punkt getroffen zu haben, und dort gezielt weiterbohren.',beispiel:'A wird spürbar lauter. B: „Aha, du wirst ja richtig emotional dabei — da habe ich wohl genau ins Schwarze getroffen."',beispiel2:'A wird sichtlich lauter. B: „Du wirst ja richtig wütend dabei — da habe ich wohl etwas Wahres getroffen."'},{nr:24,titel:'An das Publikum appellieren',beschreibung:'Statt in der Sache zu überzeugen, beim Publikum populäre, aber unsinnige Argumente vorbringen.',beispiel:'B, zu den Umstehenden gewandt: „Das sieht doch jeder hier sofort, dass das keinen Sinn ergibt, oder?"',beispiel2:'Vor gemeinsamen Freunden: „Ihr seht doch alle, dass ich hier eindeutig recht habe, oder nicht?"'},{nr:25,titel:'Auf Autorität pochen',beschreibung:'Sich auf eine anerkannte Autorität berufen, statt selbst inhaltlich zu argumentieren.',beispiel:'B: „Sogar Einstein hat schon gesagt, dass..." — obwohl das Zitat mit dem eigentlichen Streitthema kaum etwas zu tun hat.',beispiel2:'B: „Mein Therapeut sieht das genauso." (Obwohl das Thema mit Therapie nichts zu tun hat.)'},{nr:26,titel:'Unverständnis vortäuschen',beschreibung:'Vorgeben, ein starkes Argument nicht zu verstehen, um Zeit zu gewinnen oder den Gegner als unklar hinzustellen.',beispiel:'B: „Tut mir leid, ich verstehe deine komplizierte Argumentation leider nicht ganz — kannst du das nochmal vereinfachen?", obwohl das Argument eigentlich klar war.',beispiel2:'B: „Ich versteh ehrlich nicht, was du meinst — kannst du das nochmal ganz einfach erklären?" (Obwohl das Argument bereits klar war.)'},{nr:27,titel:'In eine verpönte Kategorie stecken',beschreibung:'Die gegnerische Position mit etwas gesellschaftlich Verrufenem in Verbindung bringen, um sie zu diskreditieren.',beispiel:'B: „Diese Position vertreten doch sonst nur Leute vom äußersten Rand des politischen Spektrums."',beispiel2:'B: „Das klingt ja fast schon kontrollierend, was du da von mir verlangst."'},{nr:28,titel:'Theorie gegen Praxis ausspielen',beschreibung:'Zugeben, dass etwas „in der Theorie" stimmt, aber behaupten, es funktioniere „in der Praxis" nicht – um sich der Konsequenz zu entziehen.',beispiel:'B: „In der Theorie klingt dein Vorschlag ja ganz nett, aber in der Praxis funktioniert so etwas einfach nie."',beispiel2:'B: „Klingt in der Theorie ja schön und gut, aber im echten Leben funktioniert so etwas erfahrungsgemäß nie."'},{nr:29,titel:'Unangenehme Fragen ignorieren',beschreibung:'Eine schwierige Frage einfach nicht beantworten und stattdessen das Thema wechseln.',beispiel:'A: „Wie viel würde das konkret kosten?" B: „Wichtiger ist doch erstmal, dass wir uns über die Ziele einig sind." (Die Zahl bleibt unbeantwortet.)',beispiel2:'Auf die konkrete Frage nach den gemeinsamen Ausgaben antwortet B nicht, sondern wechselt sofort zu einem anderen Thema.'},{nr:30,titel:'Motive statt Argumente angreifen',beschreibung:'Unterstellen, der Gegner argumentiere nur aus Eigeninteresse, statt sich mit dem Inhalt zu befassen.',beispiel:'B: „Du sagst das doch nur, weil du selbst finanziell davon profitieren würdest." (Ob das Argument inhaltlich stimmt, bleibt unbeantwortet.)',beispiel2:'B: „Du sagst das doch nur, weil du selbst keine Lust hast, das zu übernehmen." (Der Inhalt des Arguments bleibt unangetastet.)'}];export const DUNKLE_RHETORIK=[{titel:'Strohmann-Argument',beschreibung:'Die Position des Gegenübers wird verzerrt oder übertrieben wiedergegeben, um die verzerrte (leichter angreifbare) Version statt der echten Aussage zu widerlegen.',beispiel:'„Du willst also, dass gar keine Regeln mehr gelten?" – obwohl nur eine einzelne Regel infrage gestellt wurde.',konter:'Ruhig die eigene Position in eigenen Worten richtigstellen: „Das habe ich nicht gesagt. Ich meinte konkret..."',beispiel2:'A: „Wir sollten unseren Konsum bewusster gestalten." B: „Du willst also, dass wir komplett auf alles verzichten und wie Asketen leben?"'},{titel:'Whataboutism',beschreibung:'Statt auf den Vorwurf einzugehen, wird auf ein (angebliches) Fehlverhalten der anderen Seite verwiesen, um vom eigentlichen Thema abzulenken.',beispiel:'„Warum redest du über mein Verhalten, wenn XY genauso schlimm ist?"',konter:'Trennen: „Das mag sein, ist aber ein anderes Thema. Bleiben wir zunächst bei diesem Punkt hier."',beispiel2:'A: „Du hast das Geschirr nicht gespült." B: „Und was ist mit dir — du hast letzte Woche den Müll vergessen!"'},{titel:'Ad Hominem',beschreibung:'Die Person wird persönlich angegriffen oder diskreditiert, statt sich mit ihrem Argument auseinanderzusetzen.',beispiel:'„Was verstehst du schon davon, du hast ja nicht mal studiert."',konter:'Auf die Sachebene zurückführen: „Lass uns über das Argument sprechen, nicht über mich."',beispiel2:'„Deine Meinung zum Sparen zählt nicht, du hast doch selbst Schulden."'},{titel:'Falsches Dilemma',beschreibung:'Es werden nur zwei Optionen präsentiert, obwohl in Wirklichkeit weitere Möglichkeiten existieren.',beispiel:'„Entweder du bist für uns, oder du bist gegen uns."',konter:'Die dritte Option benennen: „Es gibt noch weitere Perspektiven, zum Beispiel..."',beispiel2:'„Entweder du unterstützt mich hier komplett, oder du bist gegen mich."'},{titel:'Gaslighting',beschreibung:'Die eigene Wahrnehmung oder Erinnerung des Gegenübers wird systematisch infrage gestellt, um ihn oder sie an sich selbst zweifeln zu lassen.',beispiel:'„Das habe ich nie gesagt, du bildest dir das ein."',konter:'Auf Fakten und Dokumentation bestehen: „Ich erinnere mich klar daran, und wir können das gern nachprüfen."',beispiel2:'„Das habe ich nie versprochen, du erinnerst dich einfach falsch."'},{titel:'Autoritätsargument-Missbrauch',beschreibung:'Eine Behauptung wird allein dadurch als wahr präsentiert, dass eine (oft fachfremde) Autorität sie vertritt.',beispiel:'„Ein bekannter Prominenter sagt das auch, also muss es stimmen."',konter:'Nachfragen: „Welche Belege sprechen unabhängig von dieser Person dafür?"',beispiel2:'„Mein Bruder, der Arzt ist, sagt das genauso." (Obwohl es um eine reine Rechtsfrage geht.)'},{titel:'Overton-Fenster verschieben',beschreibung:'Bewusst extreme Positionen ins Spiel bringen, damit die eigentlich gewünschte, moderatere Position im Vergleich plötzlich gemäßigt wirkt.',beispiel:'Eine radikale Forderung stellen, damit die eigentliche Forderung danach vergleichsweise akzeptabel erscheint.',konter:'Die Verschiebung benennen: „Lass uns über die eigentliche Frage sprechen, nicht über das Extrembeispiel."',beispiel2:'In einer Gehaltsverhandlung wird zunächst eine utopisch hohe Forderung gestellt, damit die eigentliche Forderung danach moderat wirkt.'},{titel:'Cherry Picking',beschreibung:'Nur die Fakten oder Beispiele auswählen, die die eigene These stützen, während widersprechende Belege verschwiegen werden.',beispiel:'Nur die eine Studie zitieren, die die eigene Meinung bestätigt, und zehn gegenteilige ignorieren.',konter:'Nach der Gesamtdatenlage fragen: „Was zeigen andere Studien oder Beispiele zu diesem Thema?"',beispiel2:'Nur die eine begeisterte Kundenbewertung wird gezeigt, die zehn kritischen werden verschwiegen.'},{titel:'Nebelkerzen werfen',beschreibung:'Durch irrelevante Details, Fachbegriffe oder Zusatzinformationen vom eigentlichen Kernpunkt ablenken.',beispiel:'Bei einer kritischen Frage plötzlich eine lange, thematisch nur locker verwandte Ausführung beginnen.',konter:'Freundlich zurückführen: „Das ist interessant, aber lass uns zuerst die ursprüngliche Frage klären."',beispiel2:'Auf die konkrete Frage nach den Ausgaben folgt eine lange, nur locker verwandte Geschichte über die schwierige Kindheit.'},{titel:'Totschlagargument',beschreibung:'Ein moralisch stark aufgeladener Vergleich oder Vorwurf beendet die Sachdiskussion abrupt, weil niemand mehr widersprechen will.',beispiel:'Eine harmlose Position sofort mit einem extremen historischen Vergleich in Verbindung bringen.',konter:'Die Unverhältnismäßigkeit benennen: „Dieser Vergleich hilft uns hier nicht weiter, reden wir konkret über die Sache."',beispiel2:'„Wenn du das nicht genauso siehst, bist du einfach herzlos."'},{titel:'Salamitaktik',beschreibung:'Eine unerwünschte Position wird nicht auf einmal, sondern in vielen kleinen, kaum widerstandsfähigen Schritten durchgesetzt.',beispiel:'Erst eine kleine Ausnahme fordern, dann schrittweise immer mehr, bis am Ende die ursprüngliche Grenze komplett verschoben ist.',konter:'Das Muster früh benennen: „Das ist bereits der dritte kleine Schritt in dieselbe Richtung – lass uns über das Gesamtziel sprechen."',beispiel2:'Erst nur „einmal die Woche" länger arbeiten, dann schrittweise täglich, bis Überstunden zur stillschweigenden Normalität geworden sind.'},{titel:'Framing / Loaded Language',beschreibung:'Durch die gezielte Wortwahl wird eine Sache bereits emotional vorentschieden, bevor überhaupt argumentiert wurde.',beispiel:'„Reform" versus „Kahlschlag" für dieselbe Maßnahme.',konter:'Neutralere Begriffe vorschlagen: „Nennen wir es beim eigentlichen Sachverhalt, nicht bei der wertenden Bezeichnung."',beispiel2:'„Ausgaben kürzen" klingt neutral, „sich gesund einschränken" klingt positiv — für ein und dieselbe Maßnahme.'},{titel:'Falsche Kausalität (Post-hoc)',beschreibung:'Weil Ereignis B nach Ereignis A eintrat, wird behauptet, A habe B verursacht – ohne echten Nachweis eines Zusammenhangs.',beispiel:'„Seit der neuen Regierung ist die Kriminalität gestiegen, also ist die Regierung schuld." (Andere Ursachen werden ignoriert.)',konter:'Nach dem tatsächlichen Wirkmechanismus fragen: „Welcher konkrete Zusammenhang wird hier behauptet, und gibt es dafür Belege?"',beispiel2:'„Seit du mit dem neuen Partner zusammen bist, geht es dir schlechter." (Ohne echten Nachweis eines Zusammenhangs.)'},{titel:'Bandwagon-Effekt',beschreibung:'Eine Position wird allein deshalb als richtig dargestellt, weil angeblich „alle" oder „die Mehrheit" sie teilen.',beispiel:'„Jeder vernünftige Mensch sieht das mittlerweile so."',konter:'Trennen: „Popularität ist kein Beweis. Welche Argumente sprechen unabhängig von der Anzahl der Anhänger dafür?"',beispiel2:'„Alle unsere Freunde kaufen sich gerade ein Eigenheim, wir sollten das auch tun."'},{titel:'Falsche Balance (False Balance)',beschreibung:'Zwei Positionen werden als gleichwertig dargestellt, obwohl die Beweislage stark zu einer Seite neigt.',beispiel:'Eine gut belegte wissenschaftliche Position wird im Gespräch wie eine „Meinung unter vielen" behandelt.',konter:'Die Beweislage benennen: „Es geht hier nicht um zwei gleich starke Meinungen, sondern um sehr unterschiedlich gut belegte Positionen."',beispiel2:'Eine wissenschaftlich gut belegte Ernährungsempfehlung wird im Gespräch wie „nur eine Meinung neben vielen anderen" behandelt.'},{titel:'Schuld durch Assoziation (Guilt by Association)',beschreibung:'Eine Position wird dadurch diskreditiert, dass man sie mit einer unbeliebten Person oder Gruppe in Verbindung bringt, die sie ebenfalls vertritt.',beispiel:'„Diese Ansicht vertreten auch zweifelhafte Leute, also muss an ihr etwas faul sein."',konter:'Trennen: „Wer eine Position sonst noch vertritt, sagt nichts darüber aus, ob sie inhaltlich stimmt."',beispiel2:'„Diese Diät befürworten auch zweifelhafte Online-Gurus, also muss daran etwas faul sein."'},{titel:'Kontinuum-Fehlschluss (Sorites)',beschreibung:'Weil sich eine Grenze nicht exakt ziehen lässt, wird behauptet, es gäbe überhaupt keinen relevanten Unterschied zwischen den Extremen.',beispiel:'„Wo genau fängt \'reich\' an? Da man das nicht exakt sagen kann, gibt es also gar keinen Unterschied zwischen arm und reich."',konter:'Auf unscharfe Grenzen, aber reale Unterschiede hinweisen: „Auch ohne exakte Grenze gibt es eindeutige Fälle auf beiden Seiten."',beispiel2:'„Wo genau fängt \'zu viel Alkohol\' an? Weil man das nicht exakt sagen kann, gibt es also gar keine sinnvolle Grenze."'},{titel:'Erschöpfung als Taktik (Gish Gallop)',beschreibung:'Eine große Zahl schwacher Behauptungen wird so schnell hintereinander vorgebracht, dass keine Zeit bleibt, jede einzelne zu widerlegen.',beispiel:'In einer Debatte werden zehn zweifelhafte Behauptungen pro Minute aufgestellt, in der Hoffnung, dass nur wenige davon widerlegt werden können.',konter:'Tempo herausnehmen: „Das waren gerade viele Behauptungen auf einmal. Lass uns eine nach der anderen prüfen, angefangen mit der wichtigsten."',beispiel2:'In einem Streitgespräch werden zehn Vorwürfe pro Minute aufgezählt, sodass keine Zeit bleibt, auch nur einen davon zu entkräften.'},{titel:'Falsche Äquivalenz',beschreibung:'Zwei tatsächlich sehr unterschiedlich schwerwiegende Dinge werden so dargestellt, als seien sie moralisch oder sachlich gleichwertig.',beispiel:'Eine kleine Unpünktlichkeit wird mit einem gravierenden Vertragsbruch auf eine Stufe gestellt.',konter:'Die Größenordnung benennen: „Das sind zwei sehr unterschiedliche Kategorien von Problemen, die man nicht gleichsetzen sollte."',beispiel2:'Eine kleine Verspätung von fünf Minuten wird mit einem ernsthaft gebrochenen Versprechen auf eine Stufe gestellt.'}];export const HELLE_RHETORIK=[{titel:'Aktives Zuhören',beschreibung:'Dem Gegenüber volle Aufmerksamkeit schenken und durch Rückfragen und Paraphrasieren zeigen, dass man die Position wirklich verstanden hat, bevor man antwortet.',beispiel:'„Wenn ich dich richtig verstehe, geht es dir vor allem um... Ist das korrekt?"',beispiel2:'„Wenn ich dich richtig verstehe, fühlst du dich gerade übergangen — stimmt das so?"'},{titel:'Steelmanning',beschreibung:'Bewusst die stärkste, überzeugendste Version der gegnerischen Position formulieren – das Gegenteil des Strohmanns – bevor man sie inhaltlich hinterfragt.',beispiel:'„Das beste Argument für deine Position ist wahrscheinlich..., trotzdem möchte ich einwenden, dass..."',beispiel2:'„Das stärkste Argument für deine Seite ist wahrscheinlich..., trotzdem sehe ich es anders, weil..."'},{titel:'Rhetorisches Dreieck (Ethos, Pathos, Logos)',beschreibung:'Aristoteles\' Modell überzeugender Rede: Glaubwürdigkeit (Ethos), emotionale Resonanz (Pathos) und stichhaltige Argumente (Logos) im Gleichgewicht einsetzen.',beispiel:'Erst eigene Kompetenz kurz belegen (Ethos), dann eine Geschichte erzählen (Pathos), dann Daten liefern (Logos).',beispiel2:'Erst die eigene Erfahrung kurz nennen (Ethos), dann eine persönliche Geschichte erzählen (Pathos), dann konkrete Zahlen liefern (Logos).'},{titel:'Offene Fragetechnik',beschreibung:'Statt zu behaupten, offene Fragen stellen, die den Gesprächspartner zum eigenen Nachdenken anregen – wie bei der sokratischen Methode.',beispiel:'„Was würde sich für dich ändern, wenn diese Annahme nicht zutrifft?"',beispiel2:'„Was würde sich für dich konkret ändern, wenn wir das anders lösen würden?"'},{titel:'Ich-Botschaften',beschreibung:'Kritik oder Widerspruch aus der eigenen Perspektive formulieren statt als Vorwurf, um Verteidigungshaltung beim Gegenüber zu vermeiden.',beispiel:'„Ich sehe das anders, weil..." statt „Du liegst falsch, weil..."',beispiel2:'„Ich fühle mich übergangen, wenn Entscheidungen ohne mich getroffen werden" statt „Du ignorierst mich einfach immer."'},{titel:'Storytelling mit Fakten',beschreibung:'Abstrakte Daten und Argumente in eine konkrete, nachvollziehbare Geschichte einbetten, damit sie im Gedächtnis bleiben und emotional wirken.',beispiel:'Statt nur eine Statistik zu nennen, ein konkretes Fallbeispiel erzählen, das die Zahl greifbar macht.',beispiel2:'Statt nur „80% sparen dadurch Energie" zu sagen, die konkrete Geschichte einer Familie erzählen, die dadurch spürbar entlastet wurde.'},{titel:'Einwandbehandlung (Feel-Felt-Found)',beschreibung:'Einen Einwand zunächst anerkennen, dann eine ähnliche Erfahrung teilen und schließlich zeigen, was sich dabei als hilfreich herausgestellt hat.',beispiel:'„Ich verstehe, dass du das so empfindest (feel). Andere haben anfangs ähnlich gedacht (felt). Was sich gezeigt hat (found), ist..."',beispiel2:'„Ich verstehe, dass dich das ärgert (feel). Mir ging es früher ähnlich (felt). Was mir geholfen hat, war... (found)."'},{titel:'Zusammenfassen & Spiegeln',beschreibung:'Die Position des Gegenübers am Ende eines Gesprächsabschnitts kurz zusammenfassen, um Missverständnisse frühzeitig sichtbar zu machen.',beispiel:'„Lass mich kurz zusammenfassen, was ich verstanden habe, bevor wir weitermachen."',beispiel2:'„Lass mich kurz zusammenfassen, was du gerade gesagt hast, bevor ich antworte."'},{titel:'Sokratisches Fragen',beschreibung:'Durch eine Kette gezielter Fragen das Gegenüber selbst zu einer Einsicht führen, statt sie direkt vorzugeben.',beispiel:'„Was genau meinst du mit \'Erfolg\'? Und würde diese Definition auch in diesem Fall noch gelten?"',beispiel2:'„Was genau meinst du mit \'gerecht\' in diesem Zusammenhang?"'},{titel:'Positives Reframing',beschreibung:'Eine Situation oder Aussage bewusst in einem konstruktiven, lösungsorientierten Licht darstellen, ohne dabei Fakten zu verzerren.',beispiel:'Statt „Das Projekt ist gescheitert" formulieren: „Wir haben viel über die Grenzen des Ansatzes gelernt."',beispiel2:'Statt „Wir haben das Ziel verfehlt" formulieren: „Wir wissen jetzt viel genauer, was nicht funktioniert."'},{titel:'Gemeinsamkeiten zuerst benennen',beschreibung:'Ein Gespräch mit dem beginnen, worüber tatsächlich Einigkeit besteht, bevor man zu den Streitpunkten kommt – schafft Vertrauen und Gesprächsbereitschaft.',beispiel:'„Wir sind uns beide einig, dass das Ziel wichtig ist. Wo wir unterschiedlicher Meinung sind, ist der Weg dorthin."',beispiel2:'„Uns beiden liegt die Familie am Herzen — lass uns von da aus über die Feiertagsplanung sprechen."'},{titel:'Präzisierende Rückfrage',beschreibung:'Statt eine unklare Aussage zu interpretieren oder anzugreifen, gezielt nachfragen, was genau gemeint ist.',beispiel:'„Was genau meinst du mit \'unfair\' in diesem Zusammenhang?"',beispiel2:'„Was meinst du genau mit \'zu wenig Zeit füreinander\'?"'},{titel:'Gemeinsame Faktenbasis schaffen',beschreibung:'Vor der eigentlichen Diskussion klären, auf welche Fakten oder Zahlen sich beide Seiten einigen können, um spätere Scheingefechte zu vermeiden.',beispiel:'„Bevor wir bewerten, was das bedeutet — sind wir uns über die zugrunde liegenden Zahlen einig?"',beispiel2:'„Bevor wir bewerten, was das bedeutet — sind wir uns über die eigentlichen Zahlen einig?"'},{titel:'Zugeständnisse machen, wo berechtigt',beschreibung:'Einen Teilaspekt der Gegenposition offen als richtig anerkennen, bevor man den eigenen Einwand vorbringt — erhöht die eigene Glaubwürdigkeit.',beispiel:'„Du hast recht, dass es hier Ausnahmen gibt. Trotzdem halte ich die grundsätzliche Regel für sinnvoll, weil..."',beispiel2:'„Du hast recht, dass ich das früher hätte ansprechen sollen. Trotzdem denke ich, dass..."'},{titel:'Konkretisieren statt abstrahieren',beschreibung:'Abstrakte Prinzipien an einem konkreten, nachvollziehbaren Einzelfall durchspielen, um Missverständnisse zu vermeiden.',beispiel:'„Lass uns das an einem konkreten Beispiel durchgehen, statt nur allgemein zu diskutieren."',beispiel2:'„Lass uns das direkt an dem Vorfall von letzter Woche durchgehen, statt nur allgemein zu diskutieren."'},{titel:'Gemeinsame Werte ansprechen',beschreibung:'An Werte appellieren, die beide Gesprächspartner teilen, statt an rein taktische oder parteiische Argumente.',beispiel:'„Uns beiden geht es doch um Fairness — lass uns von da aus weiterdenken."',beispiel2:'„Uns beiden ist Verlässlichkeit wichtig — lass uns von da aus weiterdenken."'},{titel:'Pausen und Bedenkzeit einräumen',beschreibung:'Bewusst innehalten, statt eine Antwort sofort zu erzwingen — verhindert vorschnelle, unüberlegte Positionen auf beiden Seiten.',beispiel:'„Das ist ein wichtiger Punkt. Lass mich kurz darüber nachdenken, bevor ich antworte."',beispiel2:'„Das ist ein wichtiger Punkt. Lass mich kurz in Ruhe darüber nachdenken, bevor ich antworte."'}];export const UEBUNGEN=[{szenario:'A: „Wir sollten den Umweltschutz in der Stadt stärker fördern."\nB: „Ach, du willst also, dass wir alle Autos verbieten und wieder in Höhlen leben?"',optionen:['Strohmann-Argument','Whataboutism','Aktives Zuhören','Autoritätsargument'],richtig:0,erklaerung:'B verzerrt A\'s moderate Forderung zu einer absurden Extremposition, um sie leichter angreifbar zu machen – klassischer Strohmann.'},{szenario:'A: „Diese Software hat einen ernsten Sicherheitsbug."\nB: „Und was ist mit der Konkurrenzsoftware, die noch viel mehr Bugs hat?"',optionen:['Steelmanning','Whataboutism','Falsches Dilemma','Framing'],richtig:1,erklaerung:'Statt auf den konkreten Vorwurf einzugehen, lenkt B mit einem Verweis auf angebliches Fehlverhalten anderer ab.'},{szenario:'A: „Deine Kalkulation hat einen Fehler in Zeile 3."\nB: „Was verstehst du schon davon – du hast ja nicht mal BWL studiert."',optionen:['Ad Hominem','Gaslighting','Sokratisches Fragen','Cherry Picking'],richtig:0,erklaerung:'B geht nicht auf den inhaltlichen Fehler ein, sondern greift die Qualifikation der Person an.'},{szenario:'A: „Wir könnten das Budget auf drei Bereiche aufteilen."\nB: „Entweder wir stecken alles ins Marketing, oder das Unternehmen geht unter."',optionen:['Falsches Dilemma','Salamitaktik','Ich-Botschaft','Overton-Fenster'],richtig:0,erklaerung:'B präsentiert nur zwei Extreme, obwohl A bereits eine dritte, differenziertere Option genannt hatte.'},{szenario:'A: „Ich erinnere mich klar, dass du dem zugestimmt hast."\nB: „Das habe ich nie gesagt. Du bildest dir das nur ein."',optionen:['Gaslighting','Nebelkerze','Autoritätsargument','Steelmanning'],richtig:0,erklaerung:'B stellt systematisch die Erinnerung von A infrage, um sie an sich selbst zweifeln zu lassen.'},{szenario:'A: „Diese Diät ist wissenschaftlich nicht belegt."\nB: „Aber ein bekannter Fitness-Influencer mit zwei Millionen Followern schwört darauf!"',optionen:['Autoritätsargument-Missbrauch','Whataboutism','Falsches Dilemma','Aktives Zuhören'],richtig:0,erklaerung:'Die Reichweite des Influencers ersetzt hier ein echtes fachliches Argument – Fitness-Reichweite belegt keine wissenschaftliche Kompetenz.'},{szenario:'In einem Bericht werden nur die drei besten Quartalszahlen der letzten zehn Jahre gezeigt, die übrigen sieben schlechteren werden weggelassen.',optionen:['Cherry Picking','Ad Hominem','Ich-Botschaft','Sokratisches Fragen'],richtig:0,erklaerung:'Nur die passenden Daten werden gezeigt, widersprechende Ergebnisse verschwiegen – klassisches Cherry Picking.'},{szenario:'Auf die kritische Frage „Warum ist das Projekt drei Monate zu spät?" antwortet der Projektleiter mit einem langen, nur locker verwandten Vortrag über die Geschichte der Firma.',optionen:['Nebelkerze','Steelmanning','Framing','Falsches Dilemma'],richtig:0,erklaerung:'Durch irrelevante Zusatzinformationen wird von der eigentlichen, unangenehmen Frage abgelenkt.'},{szenario:'Erst wird eine kleine Ausnahme von der Regel gefordert. Zwei Monate später wird diese Ausnahme als Begründung genutzt, um die ganze Regel abzuschaffen.',optionen:['Salamitaktik','Gaslighting','Aktives Zuhören','Autoritätsargument'],richtig:0,erklaerung:'Die unerwünschte Position wird nicht auf einmal, sondern in vielen kleinen, kaum widerstandsfähigen Schritten durchgesetzt.'},{szenario:'Für dieselbe Gesetzesänderung wird je nach Lager von „Reform" oder von „Kahlschlag" gesprochen.',optionen:['Framing / Loaded Language','Whataboutism','Sokratisches Fragen','Cherry Picking'],richtig:0,erklaerung:'Die Wortwahl entscheidet emotional vor, bevor überhaupt inhaltlich argumentiert wurde.'},{szenario:'B antwortet auf eine lange Erklärung von A mit: „Wenn ich dich richtig verstehe, geht es dir vor allem darum, dass die Frist realistisch bleibt. Habe ich das richtig verstanden?"',optionen:['Aktives Zuhören','Ad Hominem','Nebelkerze','Falsches Dilemma'],richtig:0,erklaerung:'B fasst die Position zusammen und fragt nach, statt sofort zu widersprechen – ein Beispiel für konstruktive, „helle" Rhetorik.'},{szenario:'B beginnt seine Erwiderung mit: „Das stärkste Argument für deine Position ist wahrscheinlich, dass es kurzfristig günstiger ist. Trotzdem denke ich, dass..."',optionen:['Steelmanning','Strohmann-Argument','Autoritätsargument','Gaslighting'],richtig:0,erklaerung:'B formuliert zunächst die stärkste Version der Gegenposition, bevor er widerspricht – das Gegenteil eines Strohmanns.'}];
